window.RF_FULL=window.RF_FULL||{};window.RF_FULL["fz226rosgv"]=[
["0","Преамбула и список изменений","","2026-08-04","РОССИЙСКАЯ ФЕДЕРАЦИЯ ФЕДЕРАЛЬНЫЙ ЗАКОН О войсках национальной гвардии Российской Федерации\nПринят Государственной Думой 22 июня 2016 года\nОдобрен Советом Федерации 29 июня 2016 года\nСписок изменяющих документов(В редакции федеральных законов от 05.12.2017 № 391-ФЗ, от 07.03.2018 № 40-ФЗ, от 29.07.2018 № 264-ФЗ, от 11.10.2018 № 364-ФЗ, от 01.10.2019 № 328-ФЗ, от 02.12.2019 № 404-ФЗ, от 18.03.2020 № 64-ФЗ, от 20.07.2020 № 235-ФЗ, от 31.07.2020 № 275-ФЗ, от 31.07.2020 № 276-ФЗ, от 26.05.2021 № 147-ФЗ, от 01.07.2021 № 279-ФЗ, от 01.04.2022 № 85-ФЗ, от 14.07.2022 № 305-ФЗ, от 14.07.2022 № 351-ФЗ, от 29.12.2022 № 638-ФЗ, от 06.02.2023 № 14-ФЗ, от 24.06.2023 № 281-ФЗ, от 04.08.2023 № 436-ФЗ, от 04.08.2023 № 440-ФЗ, от 04.08.2023 № 446-ФЗ, от 26.02.2024 № 27-ФЗ, от 22.04.2024 № 82-ФЗ, от 08.08.2024 № 279-ФЗ, от 31.07.2025 № 320-ФЗ, от 15.12.2025 № 467-ФЗ, от 08.03.2026 № 52-ФЗ, от 25.04.2026 № 109-ФЗ, от 25.05.2026 № 150-ФЗ, от 04.08.2026 № 328-ФЗ, от 04.08.2026 № 330-ФЗ)"],
["1","Войска национальной гвардии Российской Федерации и их предназначение","Глава 1. Общие положения","","Статья 1. Войска национальной гвардии Российской Федерации и их предназначение\nВойска национальной гвардии Российской Федерации (далее - войска национальной гвардии) являются государственной военной организацией, предназначенной для обеспечения государственной и общественной безопасности, защиты прав и свобод человека и гражданина."],
["2","Задачи войск национальной гвардии","Глава 1. Общие положения","2018-03-07","Статья 2. Задачи войск национальной гвардии\n1. На войска национальной гвардии возлагается выполнение следующих задач:\n1) участие в охране общественного порядка, обеспечении общественной безопасности;\n2) охрана важных государственных объектов, специальных грузов, сооружений на коммуникациях в соответствии с перечнями, утвержденными Правительством Российской Федерации;\n3) участие в борьбе с терроризмом и экстремизмом;\n4) участие в обеспечении режимов чрезвычайного положения, военного положения, правового режима контртеррористической операции;\n5) участие в территориальной обороне Российской Федерации;\n6) оказание содействия пограничным органам федеральной службы безопасности в охране Государственной границы Российской Федерации;\n7) федеральный государственный контроль (надзор) за соблюдением законодательства Российской Федерации в области оборота оружия и в области частной охранной и частной детективной деятельности, а также за обеспечением безопасности объектов топливно-энергетического комплекса, за деятельностью подразделений охраны юридических лиц с особыми уставными задачами и подразделений ведомственной охраны; (В редакции Федерального закона от 05.12.2017 № 391-ФЗ)\n8) охрана особо важных и режимных объектов, объектов, подлежащих обязательной охране войсками национальной гвардии, в соответствии с перечнем, утвержденным Правительством Российской Федерации, охрана имущества физических и юридических лиц по договорам;\n9) обеспечение по решению Президента Российской Федерации безопасности высших должностных лиц субъектов Российской Федерации (руководителей высших исполнительных органов государственной власти субъектов Российской Федерации) и иных лиц. (Дополнение пунктом - Федеральный закон от 07.03.2018 № 40-ФЗ)\n2. Иные задачи на войска национальной гвардии могут быть возложены решениями Президента Российской Федерации, принятыми в соответствии с федеральными конституционными законами и федеральными законами."],
["3","Правовая основа деятельности войск национальной гвардии","Глава 1. Общие положения","2023-08-04","Статья 3. Правовая основа деятельности войск национальной гвардии\nПравовую основу деятельности войск национальной гвардии составляют Конституция Российской Федерации, общепризнанные принципы и нормы международного права, международные договоры Российской Федерации, федеральные конституционные законы, настоящий Федеральный закон, другие федеральные законы, нормативные правовые акты Президента Российской Федерации, Правительства Российской Федерации, а также нормативные правовые акты федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере деятельности войск национальной гвардии Российской Федерации, в сфере оборота оружия, в сфере частной охранной деятельности, в сфере частной детективной деятельности, в сфере вневедомственной охраны, а также в сфере обеспечения общественной безопасности в пределах своих полномочий (далее - уполномоченный федеральный орган исполнительной власти), и иные нормативные правовые акты Российской Федерации, регулирующие деятельность войск национальной гвардии. (В редакции Федерального закона от 04.08.2023 № 436-ФЗ)"],
["4","Принципы деятельности войск национальной гвардии","Глава 1. Общие положения","","Статья 4. Принципы деятельности войск национальной гвардии\nВойска национальной гвардии осуществляют свою деятельность на основе принципов законности, соблюдения прав и свобод человека и гражданина, единоначалия и централизации управления."],
["4.1","Соблюдение прав и свобод человека и гражданина в деятельности войск национальной гвардии","Глава 1. Общие положения","2023-08-04","Статья 4.1. Соблюдение прав и свобод человека и гражданина в деятельности войск национальной гвардии\n1. При осуществлении полномочий, предусмотренных пунктами 4, 16, 18, 24, 26, 27 части 1 статьи 9 настоящего Федерального закона, на лицо, проходящее службу в войсках национальной гвардии и имеющее специальное звание полиции (далее - сотрудник), возлагается обязанность назвать свои должность, звание, фамилию, предъявить по требованию гражданина служебное удостоверение, после чего сообщить причину и цель обращения, а в случае применения к гражданину мер, ограничивающих его права и свободы, разъяснить ему причину и основания применения таких мер, а также возникающие в связи с этим права и обязанности гражданина. (В редакции Федерального закона от 04.08.2023 № 436-ФЗ)\n2. Сотрудник войск национальной гвардии имеет право не исполнять требования, предусмотренные частью 1 настоящей статьи, при возникновении обстоятельств, создающих непосредственную угрозу жизни и здоровью сотрудника войск национальной гвардии или иных лиц, а также при необходимости незамедлительного пресечения преступления или административного правонарушения либо преследования совершивших их лиц.\n(Дополнение статьей - Федеральный закон от 31.07.2020 № 275-ФЗ)"],
["5","Общий состав войск национальной гвардии","Глава 1. Общие положения","2023-08-04","Статья 5. Общий состав войск национальной гвардии\n1. В состав войск национальной гвардии входят:\n1) органы управления;\n2) объединения, соединения и воинские части;\n3) подразделения (органы), в том числе в которых проходят службу сотрудники (далее - подразделения); (В редакции Федерального закона от 04.08.2023 № 436-ФЗ)\n4) образовательные организации высшего образования и иные организации.\n2. Органы управления объединений, органы управления соединений, воинские части, подразделения, образовательные организации высшего образования и иные организации войск национальной гвардии могут быть юридическими лицами в организационно-правовой форме государственного учреждения.\n3. Создание, реорганизация и упразднение (ликвидация) воинских частей и подразделений войск национальной гвардии осуществляются руководителем уполномоченного федерального органа исполнительной власти.\n4. Органы управления объединений, подразделения и организации войск национальной гвардии, являющиеся юридическими лицами, действуют на основании уставов, утверждаемых руководителем уполномоченного федерального органа исполнительной власти.\n5. Органы управления соединений и воинские части войск национальной гвардии, являющиеся юридическими лицами, действуют на основании единого типового устава, утверждаемого руководителем уполномоченного федерального органа исполнительной власти."],
["6","Руководство и управление войсками национальной гвардии","Глава 1. Общие положения","2023-08-04","Статья 6. Руководство и управление войсками национальной гвардии\n1. Руководство войсками национальной гвардии осуществляет Президент Российской Федерации.\n2. Президент Российской Федерации:\n1) определяет задачи войск национальной гвардии;\n2) утверждает структуру и состав войск национальной гвардии (до оперативно-территориального объединения включительно);\n3) утверждает штатную численность военнослужащих войск национальной гвардии, сотрудников и гражданского персонала войск национальной гвардии; (В редакции Федерального закона от 04.08.2023 № 436-ФЗ)\n4) назначает на должность главнокомандующего войсками национальной гвардии и освобождает его от должности;\n5) учреждает геральдический знак - эмблему, знамя и флаг войск национальной гвардии, флаг уполномоченного федерального органа исполнительной власти, флаг руководителя уполномоченного федерального органа исполнительной власти, знамена территориальных органов уполномоченного федерального органа исполнительной власти и утверждает положения о них, их описания и рисунки; (В редакции Федерального закона от 01.04.2022 № 85-ФЗ)\n5.1) учреждает флаг кораблей, катеров и судов войск национальной гвардии, вымпел кораблей и катеров войск национальной гвардии и утверждает их описания и рисунки; (Дополнение пунктом - Федеральный закон от 01.04.2022 № 85-ФЗ)\n5.2) определяет порядок охраны важных государственных объектов, специальных грузов, сооружений на коммуникациях, подлежащих охране войсками национальной гвардии; (Дополнение пунктом - Федеральный закон от 01.04.2022 № 85-ФЗ)\n6) утверждает положение об оперативно-территориальном объединении войск национальной гвардии;\n7) устанавливает количество должностей в войсках национальной гвардии, подлежащих замещению высшими офицерами (высшим начальствующим составом), присваивает воинские звания высших офицеров (специальные звания высшего начальствующего состава), назначает военнослужащих (сотрудников) на воинские должности (должности), для которых штатом предусмотрены воинские звания высших офицеров (специальные звания высшего начальствующего состава), освобождает их от воинских должностей (должностей) и увольняет их с военной службы в порядке, предусмотренном федеральным законом;\n8) утверждает концепцию и план строительства и развития войск национальной гвардии;\n9) осуществляет иные полномочия в соответствии с Конституцией Российской Федерации, федеральными конституционными законами и федеральными законами.\n3. Правительство Российской Федерации:\n1) осуществляет выделение финансовых средств для обеспечения деятельности войск национальной гвардии в пределах сумм, установленных федеральным законом о федеральном бюджете на соответствующий год, а также обеспечивает выделение необходимых материально-технических ресурсов;\n2) утверждает перечень состоящих на вооружении войск национальной гвардии вооружения, боеприпасов, военной и специальной техники, специальных средств; (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n3) обеспечивает оснащение войск национальной гвардии вооружением, боеприпасами, военной и специальной техникой, специальными средствами по их заказам; (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n4) утверждает перечни важных государственных объектов, специальных грузов, сооружений на коммуникациях, подлежащих охране войсками национальной гвардии;\n5) утверждает перечень объектов, подлежащих обязательной охране войсками национальной гвардии;\n6) осуществляет в пределах своих полномочий мероприятия по социальной защите, материальному обеспечению военнослужащих (сотрудников) войск национальной гвардии, граждан Российской Федерации, уволенных с военной службы из внутренних войск, уволенных с военной службы (службы) в войсках национальной гвардии, членов их семей, лиц, находящихся (находившихся) на иждивении сотрудников (граждан Российской Федерации, уволенных со службы в войсках национальной гвардии), и гражданского персонала; (В редакции федеральных законов от 29.07.2018 № 264-ФЗ, от 31.07.2020 № 276-ФЗ)\n6.1) утверждает перечень отдельных категорий сотрудников, которые имеют право на питание за счет средств федерального бюджета и которым по их просьбе выдается продовольственный паек, устанавливает порядок и нормы выдачи продовольственного пайка и его ассортимент; (Дополнение пунктом - Федеральный закон от 31.07.2020 № 276-ФЗ)\n7) обеспечивает реализацию гарантий правовой защиты и социальной поддержки военнослужащих (сотрудников) войск национальной гвардии, граждан Российской Федерации, уволенных с военной службы из внутренних войск, уволенных с военной службы (службы) в войсках национальной гвардии, членов их семей, лиц, находящихся (находившихся) на иждивении сотрудников (граждан Российской Федерации, уволенных со службы в войсках национальной гвардии), и гражданского персонала; (В редакции Федерального закона от 29.07.2018 № 264-ФЗ)\n8) утверждает перечень водных объектов, расположенных в районах с наиболее ценными природными ресурсами, на акваториях которых воинские части войск национальной гвардии участвуют в охране общественного порядка;\n9) определяет порядок использования авиации войск национальной гвардии в интересах других федеральных органов исполнительной власти;\n10) утверждает требования к оборудованию инженерно-техническими средствами охраны важных государственных объектов, специальных грузов, сооружений на коммуникациях, подлежащих охране войсками национальной гвардии, порядок контроля за их выполнением и эксплуатацией указанных инженерно-технических средств охраны, если иное не установлено законодательством Российской Федерации в области использования атомной энергии;\n11) осуществляет иные полномочия в соответствии с Конституцией Российской Федерации, федеральными конституционными законами, федеральными законами и указами Президента Российской Федерации.\n4. Управление войсками национальной гвардии осуществляет руководитель уполномоченного федерального органа исполнительной власти, являющийся главнокомандующим войсками национальной гвардии."],
["7","Дислокация войск национальной гвардии","Глава 1. Общие положения","","Статья 7. Дислокация войск национальной гвардии\n1. Объединения, соединения, воинские части и подразделения войск национальной гвардии дислоцируются в соответствии с задачами войск национальной гвардии и с учетом социально-экономических условий мест дислокации.\n2. Места дислокации воинских частей и подразделений войск национальной гвардии определяются решением руководителя уполномоченного федерального органа исполнительной власти, а от соединения и выше - решением Президента Российской Федерации.\n3. Передислокация воинских частей и подразделений войск национальной гвардии осуществляется по решению руководителя уполномоченного федерального органа исполнительной власти, а от соединения и выше - по решению Президента Российской Федерации."],
["8","Полномочия войск национальной гвардии","Глава 2. Полномочия войск национальной гвардии","2024-04-22","Статья 8. Полномочия войск национальной гвардии\n1. Войска национальной гвардии в целях выполнения возложенных на них задач осуществляют следующие полномочия:\n1) общие полномочия;\n2) специальные полномочия (меры принуждения): задержание; вскрытие транспортного средства; вхождение (проникновение) в жилые и иные помещения, на земельные участки и территории (акватории); оцепление (блокирование) участков местности (акваторий), жилых и иных помещений, строений и других объектов; формирование и ведение банков данных о гражданах; создание, развитие и эксплуатация государственных информационных систем; (В редакции Федерального закона от 22.04.2024 № 82-ФЗ)\n3) полномочия по обеспечению режимов чрезвычайного положения, военного положения и правового режима контртеррористической операции и полномочия, связанные с участием в контртеррористической операции;\n4) иные полномочия, предусмотренные федеральными конституционными законами, настоящим Федеральным законом, другими федеральными законами и иными нормативными правовыми актами Российской Федерации.\n2. Полномочия войск национальной гвардии реализуются органами управления, объединениями, соединениями, воинскими частями, подразделениями, организациями и военнослужащими (сотрудниками) войск национальной гвардии в порядке, предусмотренном федеральными конституционными законами, настоящим Федеральным законом, другими федеральными законами, нормативными правовыми актами Президента Российской Федерации, Правительства Российской Федерации, а также нормативными правовыми актами уполномоченного федерального органа исполнительной власти с соблюдением требований законодательства Российской Федерации о защите государственной тайны.\n3. Законные требования военнослужащих (сотрудников) войск национальной гвардии при реализации ими полномочий войск национальной гвардии обязательны для исполнения гражданами и должностными лицами."],
["9","Общие полномочия войск национальной гвардии","Глава 2. Полномочия войск национальной гвардии","2026-05-25","Статья 9. Общие полномочия войск национальной гвардии\n1. Войска национальной гвардии наделены следующими полномочиями:\n1) требовать от граждан соблюдения общественного порядка;\n2) требовать от граждан и должностных лиц прекращения противоправных действий;\n3) пресекать преступления, административные правонарушения и противоправные действия;\n4) проверять документы, удостоверяющие личность граждан, если имеются данные, дающие основания подозревать их в совершении преступления или полагать, что они находятся в розыске, либо если имеется повод к возбуждению в отношении этих граждан дела об административном правонарушении, либо если имеются основания для их задержания в случаях, предусмотренных федеральным законом;\n5) осуществлять производство по делам об административных правонарушениях в соответствии с законодательством Российской Федерации об административных правонарушениях;\n6) принимать необходимые меры по охране места происшествия до прибытия представителей органов следствия или дознания, требовать от граждан покинуть место происшествия;\n7) доставлять граждан в служебное помещение органа внутренних дел (полиции) в целях решения вопроса о задержании гражданина; установления личности гражданина, если имеются основания полагать, что он находится в розыске как скрывшийся от органов дознания, следствия или суда либо как уклоняющийся от исполнения уголовного наказания; защиты гражданина от непосредственной угрозы его жизни или здоровью в случае, если он не способен позаботиться о себе либо если опасности невозможно избежать иным способом;\n8) производить досмотр транспортных средств, плавучих средств (судов), нарушивших правила, установленные на охраняемых войсками национальной гвардии объектах;\n9) производить в пунктах пропуска личный досмотр работников охраняемых войсками национальной гвардии важных государственных объектов;\n10) требовать от граждан соблюдения пропускного и внутриобъектового режимов на охраняемых войсками национальной гвардии объектах; производить досмотр и (или) осмотр граждан, посещающих эти объекты, осмотр находящихся при них вещей, досмотр и (или) осмотр транспортных средств, плавучих средств (судов) при входе (въезде) на территории охраняемых объектов (акваторий) и выходе (выезде) с территорий охраняемых объектов (акваторий); при выявлении нарушений, создающих на охраняемых объектах угрозу безопасности граждан, и условий, способствующих хищениям имущества, принимать меры по пресечению выявленных нарушений и устранению указанных условий;\n11) беспрепятственно входить в любое время суток на территории и в помещения охраняемых войсками национальной гвардии объектов, осматривать их в целях пресечения преступлений или административных правонарушений, а также в целях задержания лиц, незаконно проникших либо пытавшихся проникнуть на охраняемые объекты;\n12) осуществлять прием от органов внутренних дел (полиции), хранение и уничтожение изъятых, добровольно сданных и найденных огнестрельного, газового, холодного и иного оружия, боеприпасов, патронов к оружию, основных частей огнестрельного оружия, осуществлять в соответствии с федеральным законом передачу находящихся в собственности Российской Федерации оружия и (или) патронов к нему в государственные военизированные организации; (В редакции федеральных законов от 06.02.2023 № 14-ФЗ, от 08.08.2024 № 279-ФЗ)\n13) при несении службы по охране общественного порядка, обеспечении общественной безопасности на акваториях водных объектов производить досмотр плавучих средств (судов);\n14) вести разведку в местах (районах) выполнения служебно-боевых задач. Организация и порядок ведения разведки войсками национальной гвардии определяются нормативными правовыми актами Президента Российской Федерации; (В редакции Федерального закона от 14.07.2022 № 351-ФЗ)\n15) в порядке, установленном уполномоченным федеральным органом исполнительной власти, выдавать (предоставлять) гражданам и организациям при наличии оснований, предусмотренных федеральным законом, лицензии на приобретение гражданского и служебного оружия; лицензии на осуществление деятельности по торговле оружием, основными частями огнестрельного оружия и патронами к нему; лицензии на экспонирование или коллекционирование оружия, основных частей огнестрельного оружия и патронов к нему; разрешения на хранение, хранение и ношение, хранение и использование оружия, на ношение и использование охотничьего оружия, на передачу иностранному гражданину охотничьего оружия для ношения и использования в целях охоты, на хранение и ношение наградного оружия, на транспортирование, ввоз на территорию Российской Федерации и вывоз с территории Российской Федерации указанного оружия и патронов к нему; разрешения на хранение и использование или хранение и ношение отдельных типов и моделей боевого ручного стрелкового и служебного оружия, полученного во временное пользование в соответствии с федеральным законом; вести в соответствии с федеральным законом учет оружия и патронов к нему; (В редакции федеральных законов от 14.07.2022 № 305-ФЗ, от 29.12.2022 № 638-ФЗ, от 04.08.2023 № 436-ФЗ)\n16) контролировать оборот гражданского, служебного и наградного оружия, боеприпасов, патронов к оружию, сохранность и техническое состояние боевого ручного стрелкового и служебного оружия, находящегося во временном пользовании у граждан и организаций, а также соблюдение гражданами и организациями законодательства Российской Федерации в области оборота оружия;\n17) выдавать юридическим лицам и гражданам Российской Федерации направления на проведение контрольного отстрела гражданского и служебного огнестрельного оружия с нарезным стволом; (В редакции Федерального закона от 05.12.2017 № 391-ФЗ)\n18) выдавать (предоставлять) в порядке, установленном уполномоченным федеральным органом исполнительной власти, при наличии оснований, предусмотренных законодательством Российской Федерации, лицензии на осуществление частной охранной деятельности или частной детективной деятельности; выдавать для подтверждения правового статуса удостоверения частного охранника и удостоверения частного детектива; проводить периодические проверки частных охранников и работников юридических лиц с особыми уставными задачами на пригодность к действиям в условиях, связанных с применением оружия и специальных средств; (В редакции федеральных законов от 05.12.2017 № 391-ФЗ, от 29.12.2022 № 638-ФЗ, от 04.08.2023 № 436-ФЗ)\n19) выдавать в соответствии с законодательством Российской Федерации во временное пользование физическим и юридическим лицам отдельные виды, типы и модели оружия и патронов к нему; (В редакции Федерального закона от 31.07.2025 № 320-ФЗ)\n20) осуществлять контроль за деятельностью частных охранных организаций и частных детективов, а также участвовать в осуществлении контроля за соблюдением организациями, осуществляющими образовательную деятельность по программам профессионального обучения частных охранников, частных детективов и дополнительным профессиональным программам для руководителей частных охранных организаций, требований и условий, установленных законодательством Российской Федерации; (В редакции Федерального закона от 05.12.2017 № 391-ФЗ)\n21) охранять на договорной основе особо важные и режимные объекты, объекты на коммуникациях, объекты, подлежащие обязательной охране в соответствии с перечнем, утверждаемым Правительством Российской Федерации, имущество граждан и организаций, а также обеспечивать оперативное реагирование на сообщения о срабатывании охранной, охранно-пожарной и тревожной сигнализации на подключенных к пультам централизованного наблюдения подразделений войск национальной гвардии объектах, охрана которых осуществляется с помощью технических средств охраны, в этих целях незамедлительно прибывать на место совершения преступления, административного правонарушения, место происшествия, пресекать противоправные деяния, устранять угрозы безопасности граждан и общественной безопасности, документировать обстоятельства совершения административного правонарушения, обстоятельства происшествия, обеспечивать сохранность следов преступления, административного правонарушения, происшествия;\n21.1) обеспечивать в порядке, утверждаемом Президентом Российской Федерации, безопасность высших должностных лиц субъектов Российской Федерации (руководителей высших исполнительных органов государственной власти субъектов Российской Федерации) и иных лиц. При этом обеспечение безопасности высших должностных лиц субъектов Российской Федерации (руководителей высших исполнительных органов государственной власти субъектов Российской Федерации) осуществляется исключительно на договорной основе; (Дополнение пунктом - Федеральный закон от 07.03.2018 № 40-ФЗ)\n22) осуществлять федеральный государственный контроль (надзор) за обеспечением безопасности объектов топливно-энергетического комплекса;\n23) осуществлять в порядке, установленном Правительством Российской Федерации, контроль за деятельностью подразделений охраны юридических лиц с особыми уставными задачами и подразделений ведомственной охраны, если иной порядок не установлен федеральным законом;\n24) проверять места производства, хранения, торговли, коллекционирования и экспонирования оружия, основных частей огнестрельного оружия, мест производства патронов к оружию и составных частей патронов, а также проверять объекты, где они обращаются, места утилизации боеприпасов; проверять у граждан документы, подтверждающие законность владения ими гражданским, служебным или наградным оружием или его использования; согласовывать требования к содержанию программ подготовки лиц в целях изучения правил безопасного обращения с оружием и приобретения навыков безопасного обращения с оружием; устанавливать порядок проверки знания правил безопасного обращения с оружием и наличия навыков безопасного обращения с оружием в организациях, определяемых Правительством Российской Федерации, и участвовать в проверке таких знаний и навыков в этих организациях; проводить проверки мест хранения и использования специальных средств в частных охранных организациях; по результатам проверок выдавать гражданам и должностным лицам обязательные для исполнения предписания об устранении выявленных нарушений правил оборота оружия, боеприпасов, патронов к оружию и специальных средств; изымать в случаях, предусмотренных законодательством Российской Федерации, оружие, боеприпасы, патроны к оружию, основные части к ним и специальные средства; ограничивать в установленном законодательством Российской Федерации порядке деятельность соответствующих объектов и применять иные меры, предусмотренные федеральным законодательством; участвовать в соответствии с законодательством Российской Федерации в проведении проверок мест производства, хранения, использования и распространения взрывчатых материалов промышленного назначения и пиротехнических изделий IV и V классов;\n25) устанавливать достоверность сведений, содержащихся в документах, представленных для принятия решения о выдаче лицензий либо разрешений, предусмотренных пунктами 15 и 18 настоящей части, в том числе путем проведения собеседования с соискателем лицензии либо разрешения, а также путем направления запросов в соответствующие правоохранительные, лицензирующие, контролирующие, надзорные и иные государственные органы, а также организации; продлевать срок действия и переоформлять выданные лицензии и разрешения, отказывать в выдаче лицензий и разрешений при наличии оснований, предусмотренных законодательством Российской Федерации; при выявлении нарушений принимать меры по приостановлению действия лицензий и разрешений, их аннулированию, а также иные меры, предусмотренные федеральным законом; продлевать срок действия, принимать решение об аннулировании удостоверения (дубликата удостоверения) частного охранника; (В редакции федеральных законов от 04.08.2023 № 440-ФЗ, от 25.05.2026 № 150-ФЗ)\n26) входить беспрепятственно по предъявлении служебного удостоверения в помещения, занимаемые частными охранными организациями и частными детективами, а также в помещения организаций, осуществляющих образовательную деятельность по программам профессионального обучения частных охранников, частных детективов и дополнительным профессиональным программам для руководителей частных охранных организаций, в целях выполнения возложенных на войска национальной гвардии обязанностей по контролю за соблюдением законодательства Российской Федерации в области частной охранной деятельности и частной детективной деятельности; осматривать места хранения специальных средств и огнестрельного оружия; проверять организацию охраны, осуществляемой частными охранными организациями, на соответствие установленным правилам; получать письменную и устную информацию о частных охранных организациях, частных охранниках, частных детективах и об организациях, осуществляющих образовательную деятельность по программам профессионального обучения частных охранников, частных детективов и дополнительным профессиональным программам для руководителей частных охранных организаций; выдавать обязательные для исполнения предписания об устранении выявленных нарушений правил частной охранной деятельности и частной детективной деятельности; (В редакции Федерального закона от 05.12.2017 № 391-ФЗ)\n27) исполнять решения суда (судьи) о возмездном изъятии или конфискации оружия и боеприпасов;\n28) носить гражданскую одежду, а также форму одежды и знаки различия сотрудников федеральных органов исполнительной власти, работников организаций в порядке, определяемом нормативными правовыми актами руководителя уполномоченного федерального органа исполнительной власти;\n29) останавливать транспортные средства, если это необходимо для выполнения возложенных на войска национальной гвардии обязанностей по участию в обеспечении безопасности дорожного движения в соответствии с законодательством Российской Федерации;\n30) пресекать массовые беспорядки в населенных пунктах, а при необходимости и в исправительных учреждениях;\n31) получать на безвозмездной основе от государственных органов и их должностных лиц информацию, необходимую для выполнения возложенных на уполномоченный федеральный орган исполнительной власти обязанностей, за исключением случаев, если федеральными законами установлен запрет на передачу такой информации;\n32) осуществлять доставление плавучих средств (судов) и орудий совершения административного правонарушения в соответствии с законодательством об административных правонарушениях; (Дополнение пунктом - Федеральный закон от 11.10.2018 № 364-ФЗ)\n33) пресекать функционирование беспилотных воздушных, подводных и надводных судов и аппаратов, беспилотных транспортных средств и иных автоматизированных беспилотных комплексов (далее - беспилотные аппараты) в целях защиты жизни и здоровья граждан и (или) военнослужащих (сотрудников) войск национальной гвардии, территорий (акваторий) охраняемых войсками национальной гвардии объектов, специальных грузов, сооружений на коммуникациях, собственных объектов войск национальной гвардии, в местах (районах) выполнения войсками национальной гвардии служебно-боевых задач, в том числе посредством подавления или преобразования сигналов дистанционного управления беспилотными аппаратами, воздействия на их пульты управления, а также повреждения или уничтожения беспилотных аппаратов. Порядок принятия решения о пресечении функционирования беспилотных аппаратов в указанных целях, а также перечень должностных лиц войск национальной гвардии, уполномоченных на принятие такого решения, определяется руководителем уполномоченного федерального органа исполнительной власти; (Дополнение пунктом - Федеральный закон от 02.12.2019 № 404-ФЗ) (В редакции Федерального закона от 04.08.2023 № 440-ФЗ)\n34) осуществлять меры по обеспечению собственной безопасности; (Дополнение пунктом - Федеральный закон от 18.03.2020 № 64-ФЗ)\n35) осуществлять прием, хранение и уничтожение изъятых, добровольно сданных или найденных взрывоопасных предметов, взрывных устройств и взрывчатых веществ; (Дополнение пунктом - Федеральный закон от 14.07.2022 № 351-ФЗ)\n36) проводить работы по поиску, обезвреживанию и (или) уничтожению взрывоопасных предметов в порядке, определяемом федеральным органом исполнительной власти в области обороны совместно с уполномоченным федеральным органом исполнительной власти и другими федеральными органами исполнительной власти, уполномоченными на организацию проведения указанных работ, оказывать помощь в реализации международных программ, проектов и операций по гуманитарному разминированию, а также выполнять взрывные работы в порядке, определяемом уполномоченным федеральным органом исполнительной власти. (Дополнение пунктом - Федеральный закон от 14.07.2022 № 351-ФЗ)\n2. При выполнении задач по охране важных государственных объектов, специальных грузов, сооружений на коммуникациях, подлежащих охране войсками национальной гвардии, уполномоченным должностным лицам войск национальной гвардии предоставляется право выдавать руководителям указанных объектов или руководителям либо должностным лицам организаций, важные государственные объекты, и (или) специальные грузы, и (или) сооружения на коммуникациях которых подлежат охране войсками национальной гвардии (за исключением руководителей (должностных лиц) объектов использования атомной энергии), обязательные для исполнения предписания об устранении выявленных в ходе осуществления своих полномочий нарушений требований к оборудованию инженерно-техническими средствами охраны важных государственных объектов, специальных грузов, сооружений на коммуникациях, подлежащих охране войсками национальной гвардии. В случае выявления указанных нарушений на объектах использования атомной энергии должностные лица войск национальной гвардии обязаны сообщить об этом в соответствующий орган управления использованием атомной энергии и федеральный орган исполнительной власти, осуществляющий федеральный государственный надзор в области использования атомной энергии, либо его территориальные органы в течение пяти рабочих дней со дня выявления таких нарушений. Порядок реализации указанных полномочий должностными лицами войск национальной гвардии и перечень таких лиц утверждаются руководителем уполномоченного федерального органа исполнительной власти.\n3. Должностные лица подразделений войск национальной гвардии вправе выдавать руководителям и должностным лицам организаций, объекты которых охраняются войсками национальной гвардии в соответствии с перечнем, утверждаемым Правительством Российской Федерации, а в случаях, предусмотренных законодательством Российской Федерации, - руководителям и должностным лицам иных организаций предписания о соблюдении установленных требований инженерно-технической укрепленности объектов и об обеспечении безопасности граждан, выдавать в ходе осуществления контроля за деятельностью подразделений охраны юридических лиц с особыми уставными задачами и подразделений ведомственной охраны, а также за обеспечением безопасности объектов топливно-энергетического комплекса, если иное не установлено федеральным законом, обязательные для исполнения предписания об устранении выявленных нарушений в их охранной деятельности, в сфере оборота оружия и обеспечении сохранности государственной и муниципальной собственности.\n4. Порядок организации взаимодействия войск национальной гвардии с федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере внутренних дел, в сфере контроля за оборотом наркотических средств, психотропных веществ и их прекурсоров, в сфере миграции (далее - федеральный орган исполнительной власти в сфере внутренних дел), его территориальными органами (подразделениями) при выполнении задач по охране общественного порядка и обеспечении общественной безопасности, полномочия должностных лиц определяются совместными нормативными правовыми актами уполномоченного федерального органа исполнительной власти и федерального органа исполнительной власти в сфере внутренних дел."],
["10","Задержание","Глава 2. Полномочия войск национальной гвардии","","Статья 10. Задержание\n1. Военнослужащие (сотрудники) войск национальной гвардии вправе задерживать до передачи в полицию:\n1) лиц, подозреваемых в совершении преступления, а также лиц, в отношении которых избрана мера пресечения в виде заключения под стражу;\n2) лиц, совершивших побег из-под стражи, а также лиц, уклоняющихся от отбывания уголовного наказания, от получения предписания о направлении к месту отбывания наказания либо не прибывших к месту отбывания наказания в установленный в указанном предписании срок;\n3) лиц, уклоняющихся от исполнения административного наказания в виде административного ареста;\n4) лиц, находящихся в розыске;\n5) лиц, в отношении которых ведется производство по делам об административных правонарушениях, отнесенных законодательством об административных правонарушениях к подведомственности войск национальной гвардии, - по основаниям, в порядке и на срок, которые предусмотрены законодательством об административных правонарушениях;\n6) лиц, допустивших нарушение правил комендантского часа;\n7) лиц, незаконно проникших либо пытавшихся проникнуть на территории охраняемых войсками национальной гвардии объектов.\n2. Лицо, подвергнутое задержанию (далее - задержанное лицо), в сопровождении военнослужащих (сотрудников) войск национальной гвардии и с соблюдением условий, исключающих угрозу их жизни и здоровью, подлежит доставлению в ближайший орган внутренних дел в кратчайший срок, но не позднее трех часов с момента задержания.\n3. В каждом случае задержания военнослужащий (сотрудник) войск национальной гвардии обязан разъяснить задержанному лицу основания задержания.\n4. Срок задержания исчисляется с момента фактического ограничения свободы передвижения задержанного лица.\n5. Задержанные лица, находящиеся при них вещи и документы, а также их транспортные средства, плавучие средства (суда) подвергаются досмотру в порядке, установленном законодательством об административных правонарушениях, если иной порядок не установлен федеральным законом.\n6. О каждом случае задержания военнослужащими (сотрудниками) войск национальной гвардии несовершеннолетнего незамедлительно уведомляются его родители или иные законные представители.\n7. О задержании военнослужащими (сотрудниками) войск национальной гвардии иностранного гражданина или подданного иностранного государства незамедлительно уведомляется дипломатическое представительство или консульское учреждение соответствующего иностранного государства в соответствии с законодательством Российской Федерации.\n8. О задержании военнослужащими (сотрудниками) войск национальной гвардии военнослужащего незамедлительно уведомляется командование воинской части, в которой этот военнослужащий проходит военную службу.\n9. Военнослужащие (сотрудники) войск национальной гвардии принимают при необходимости меры по оказанию задержанному лицу первой помощи, а также меры по устранению возникшей при задержании угрозы жизни и здоровью граждан или имуществу."],
["11","Вскрытие транспортного средства","Глава 2. Полномочия войск национальной гвардии","2023-08-04","Статья 11. Вскрытие транспортного средства\n1. Войска национальной гвардии имеют право производить вскрытие транспортного средства, в том числе проникновение в него при несении боевой службы (службы), в случаях, предусмотренных законодательством Российской Федерации, а также:\n1) для спасения жизни граждан;\n2) для обеспечения безопасности граждан или общественной безопасности при массовых беспорядках и чрезвычайных ситуациях;\n3) для задержания лиц, подозреваемых или обвиняемых в совершении преступления;\n4) для пресечения преступления;\n5) для проведения осмотра транспортного средства и (или) груза, если имеются основания полагать, что в транспортном средстве находятся без специального разрешения предметы или вещи, изъятые из гражданского оборота или ограниченно оборотоспособные;\n6) для проверки сообщения об угрозе террористического акта;\n7) для установления обстоятельств несчастного случая.\n2. Перед вскрытием транспортного средства, за исключением случаев, когда это не представляется возможным, военнослужащий (сотрудник) войск национальной гвардии обязан назвать свои должность, звание, фамилию, предъявить по требованию собственника либо иного законного владельца транспортного средства или находящихся в нем граждан служебное удостоверение, предупредить о своем намерении, разъяснить им причину и основания вскрытия транспортного средства, а также возникающие в связи с этим права и обязанности граждан.\n3. О вскрытии транспортного средства не позднее 24 часов с момента вскрытия транспортного средства информируется собственник транспортного средства, если такое вскрытие было осуществлено в его отсутствие, в порядке, определяемом уполномоченным федеральным органом исполнительной власти. (В редакции Федерального закона от 04.08.2023 № 436-ФЗ)\n4. Войска национальной гвардии в отсутствие собственника или иного законного владельца вскрытого транспортного средства обеспечивают недопущение доступа посторонних лиц в транспортное средство."],
["12","Вхождение (проникновение) в жилые и иные помещения, на земельные участки и территории (акватории)","Глава 2. Полномочия войск национальной гвардии","","Статья 12. Вхождение (проникновение) в жилые и иные помещения, на земельные участки и территории (акватории)\n1. Вхождение (проникновение) военнослужащих (сотрудников) войск национальной гвардии в жилые помещения, в иные помещения и на земельные участки, принадлежащие гражданам, в помещения, на земельные участки и территории, занимаемые организациями независимо от форм собственности (за исключением помещений, земельных участков и территорий дипломатических представительств и консульских учреждений иностранных государств, представительств международных организаций), в акватории допускается при несении боевой службы в случаях, предусмотренных законодательством Российской Федерации, а также:\n1) для защиты (спасения) жизни граждан и (или) их имущества, обеспечения безопасности граждан или общественной безопасности при массовых беспорядках и чрезвычайных ситуациях;\n2) для осуществления мероприятий по борьбе с терроризмом и экстремизмом;\n3) для задержания лиц, подозреваемых в совершении преступления;\n4) для пресечения преступления.\n2. При вхождении (проникновении) в жилые помещения, в иные помещения и на земельные участки, принадлежащие гражданам, в помещения, на земельные участки и территории, занимаемые организациями, военнослужащий (сотрудник) войск национальной гвардии вправе при необходимости произвести взлом (разрушение) запирающих устройств, элементов и конструкций, препятствующих проникновению в указанные помещения и на указанные земельные участки и территории, и осмотр находящихся там объектов и транспортных средств.\n3. Военнослужащий (сотрудник) войск национальной гвардии, осуществляющий вхождение (проникновение) в жилое помещение, обязан:\n1) перед тем как войти в жилое помещение, уведомить находящихся там граждан об основаниях вхождения (проникновения), за исключением случаев, если промедление создает непосредственную угрозу жизни или здоровью граждан и военнослужащих (сотрудников) войск национальной гвардии или может повлечь иные тяжкие последствия;\n2) при вхождении (проникновении) в жилое помещение помимо воли находящихся там граждан использовать безопасные способы и средства, с уважением относиться к чести, достоинству, жизни и здоровью граждан, не допускать без необходимости причинения ущерба их имуществу;\n3) не разглашать ставшие известными ему в связи с вхождением (проникновением) в жилое помещение факты частной жизни находящихся там граждан;\n4) сообщить непосредственному командиру (начальнику) и в течение 24 часов представить рапорт о факте вхождения (проникновения) в жилое помещение.\n4. О каждом случае вхождения (проникновения) военнослужащего (сотрудника) войск национальной гвардии в жилое помещение в возможно короткий срок, но не позднее 24 часов с момента вхождения (проникновения) информируются собственник этого помещения и (или) проживающие в нем граждане, если такое вхождение (проникновение) было осуществлено в их отсутствие.\n5. О каждом случае вхождения (проникновения) военнослужащего (сотрудника) войск национальной гвардии в жилое помещение помимо воли проживающих (находящихся) в нем граждан письменно уведомляется прокурор в течение 24 часов.\n6. Порядок информирования военнослужащим (сотрудником) войск национальной гвардии своего непосредственного командира (начальника), собственника помещения и (или) проживающих в нем граждан и прокурора о случае вхождения (проникновения) в жилое помещение определяется руководителем уполномоченного федерального органа исполнительной власти.\n7. Военнослужащие (сотрудники) войск национальной гвардии принимают меры по недопущению доступа посторонних лиц в жилые помещения, в иные помещения и на земельные участки, принадлежащие гражданам, в помещения, на земельные участки и территории, занимаемые организациями, и по охране находящегося там имущества, если вхождение (проникновение) сопровождалось действиями, предусмотренными частью 2 настоящей статьи."],
["13","Оцепление (блокирование) участков местности (акваторий), жилых и иных помещений, строений и других объектов","Глава 2. Полномочия войск национальной гвардии","2021-07-01","Статья 13. Оцепление (блокирование) участков местности (акваторий), жилых и иных помещений, строений и других объектов\n1. Военнослужащие (сотрудники) войск национальной гвардии вправе производить оцепление (блокирование) участков местности (акватории):\n1) при ликвидации последствий аварий, катастроф природного и техногенного характера и других чрезвычайных ситуаций, при проведении карантинных мероприятий во время эпидемий и (или) эпизоотий;\n2) при проведении мероприятий по пресечению массовых беспорядков и иных действий, нарушающих движение транспорта, работу средств связи и организаций;\n3) при розыске лиц, совершивших побег из-под стражи, и лиц, уклоняющихся от отбывания уголовного наказания;\n4) при преследовании лиц, подозреваемых в совершении преступления;\n5) при проверке сведений об обнаружении взрывчатых веществ или взрывных устройств либо ядовитых или радиоактивных веществ;\n6) при пресечении попыток лиц незаконно проникнуть на территории (акватории) (покинуть территории (акватории) охраняемых войсками национальной гвардии объектов. (Дополнение пунктом - Федеральный закон от 01.07.2021 № 279-ФЗ)\n2. При оцеплении (блокировании) участков местности (акватории) может быть ограничено или запрещено движение транспорта и пешеходов, плавучих средств (судов) и пловцов, если это необходимо для обеспечения безопасности граждан и общественного порядка, проведения следственных действий, оперативно-разыскных мероприятий, охраны места совершения преступления или административного правонарушения, места происшествия, а также для защиты объектов собственности, которым угрожает опасность.\n3. Оцепление (блокирование) может осуществляться также в отношении жилых помещений, строений и других объектов, принадлежащих гражданам и организациям, если это необходимо для предотвращения угрозы жизни или здоровью граждан, которые не могут быть защищены иным способом.\n4. При осуществлении действий, указанных в частях 1 - 3 настоящей статьи, военнослужащие (сотрудники) войск национальной гвардии принимают меры по обеспечению нормальной жизнедеятельности населения, разъясняют гражданам наиболее удобные в создавшейся обстановке маршруты передвижения.\n5. Порядок и перечень должностных лиц, принимающих решение об осуществлении оцепления (блокирования) участков местности (акватории), жилых помещений, строений и других объектов, определяются руководителем уполномоченного федерального органа исполнительной власти по согласованию с федеральным органом исполнительной власти в сфере внутренних дел."],
["14","Формирование и ведение банков данных о гражданах","Глава 2. Полномочия войск национальной гвардии","2017-12-05","Статья 14. Формирование и ведение банков данных о гражданах\n1. Войска национальной гвардии вправе обрабатывать данные о гражданах, необходимые для выполнения возложенных на войска национальной гвардии задач, с последующим внесением полученной информации в банки данных о гражданах (далее - банки данных).\n2. Формирование и ведение банков данных осуществляются войсками национальной гвардии в соответствии с требованиями, установленными законодательством Российской Федерации.\n3. Внесению в банки данных подлежит информация:\n1) о лицах, получивших удостоверение частного охранника;\n2) о лицах, владеющих оружием;\n3) о лицах, получивших лицензию на осуществление частной детективной (сыскной) деятельности. (Дополнение пунктом - Федеральный закон от 05.12.2017 № 391-ФЗ)\n4. Войска национальной гвардии обеспечивают защиту информации, содержащейся в банках данных, от неправомерного и случайного доступа, уничтожения, копирования, распространения и иных неправомерных действий.\n5. Информация, содержащаяся в банках данных, предоставляется органам внутренних дел (полиции) и их должностным лицам, а в случаях, предусмотренных федеральным законом, государственным органам и их должностным лицам; правоохранительным органам иностранных государств и международным полицейским организациям в соответствии с международными договорами Российской Федерации.\n6. Войска национальной гвардии обязаны обеспечить гражданину возможность ознакомления в порядке, установленном законодательством Российской Федерации, с содержащейся в банках данных информацией, непосредственно затрагивающей его права и свободы.\n7. Обработка персональных данных осуществляется в соответствии с требованиями, установленными законодательством Российской Федерации в области персональных данных.\n8. Персональные данные, содержащиеся в банках данных, подлежат уничтожению по достижении целей обработки или в случае утраты необходимости в достижении этих целей."],
["14.1","Государственная информационная система в сфере оборота оружия, в сфере частной охранной и частной детективной деятельности, в сфере вневедомственной охраны, в сфере федерального государственного контроля (надзора) за обеспечением безопасности объектов топливно-энергетического комплекса, за деятельностью подразделений охраны юридических лиц с особыми уставными задачами и подразделений ведомственной охраны","Глава 2. Полномочия войск национальной гвардии","2025-12-15","Статья 14.1. Государственная информационная система в сфере оборота оружия, в сфере частной охранной и частной детективной деятельности, в сфере вневедомственной охраны, в сфере федерального государственного контроля (надзора) за обеспечением безопасности объектов топливно-энергетического комплекса, за деятельностью подразделений охраны юридических лиц с особыми уставными задачами и подразделений ведомственной охраны\n(Наименование в редакции Федерального закона от 15.12.2025 № 467-ФЗ)\n1. В целях выполнения войсками национальной гвардии задач, предусмотренных пунктами 7 и 8 части 1 статьи 2 настоящего Федерального закона, а также формирования и ведения банков данных, указанных в статье 14 настоящего Федерального закона, уполномоченным федеральным органом исполнительной власти может создаваться, развиваться и эксплуатироваться государственная информационная система в сфере оборота оружия, в сфере частной охранной и частной детективной деятельности, в сфере вневедомственной охраны, в сфере федерального государственного контроля (надзора) за обеспечением безопасности объектов топливно-энергетического комплекса, за деятельностью подразделений охраны юридических лиц с особыми уставными задачами и подразделений ведомственной охраны (далее - государственная информационная система). (В редакции Федерального закона от 15.12.2025 № 467-ФЗ)\n2. Оператором государственной информационной системы является уполномоченный федеральный орган исполнительной власти. (В редакции Федерального закона от 15.12.2025 № 467-ФЗ)\n3. Положение о государственной информационной системе, предусматривающее в том числе порядок доступа к сведениям, содержащимся в ней, перечень получателей сведений, перечень поставщиков сведений, состав сведений, предоставляемых ими в государственную информационную систему, порядок и сроки предоставления сведений в государственную информационную систему, утверждается Правительством Российской Федерации. (В редакции Федерального закона от 15.12.2025 № 467-ФЗ)\n4. К сведениям, предоставляемым в государственную информационную систему, относятся сведения о физических и юридических лицах, об индивидуальных предпринимателях и о законных представителях указанных лиц, иные сведения, которые подлежат размещению в государственной информационной системе. (В редакции Федерального закона от 15.12.2025 № 467-ФЗ)\n(Дополнение статьей - Федеральный закон от 22.04.2024 № 82-ФЗ)"],
["15","Полномочия войск национальной гвардии по обеспечению режимов чрезвычайного положения, военного положения, правового режима контртеррористической операции, а также полномочия, связанные с участием в контртеррористической операции","Глава 2. Полномочия войск национальной гвардии","","Статья 15. Полномочия войск национальной гвардии по обеспечению режимов чрезвычайного положения, военного положения, правового режима контртеррористической операции, а также полномочия, связанные с участием в контртеррористической операции\n1. Военнослужащие (сотрудники) войск национальной гвардии в целях обеспечения режима чрезвычайного положения вправе:\n1) временно запрещать или ограничивать движение транспортных средств и пешеходов на улицах и дорогах, плавучих средств (судов) и пловцов на акватории, осуществлять их досмотр в целях защиты жизни, здоровья и имущества граждан;\n2) использовать в неотложных случаях транспортные средства, принадлежащие организациям (за исключением транспортных средств, принадлежащих дипломатическим представительствам и консульским учреждениям иностранных государств, представительствам международных организаций, а также транспортных средств специального назначения), транспортные средства и плавучие средства (суда), принадлежащие организациям или гражданам, для проезда к месту чрезвычайных ситуаций и при других чрезвычайных обстоятельствах, для доставления в медицинские организации лиц, нуждающихся в скорой медицинской помощи, а также для преследования лиц, совершивших преступления или подозреваемых в их совершении, и доставления их в полицию;\n3) не допускать граждан в целях защиты их жизни, здоровья и имущества на отдельные участки местности и объекты; обязывать их покинуть указанные участки местности и объекты;\n4) беспрепятственно пользоваться в служебных целях линиями, каналами и средствами связи, принадлежащими организациям (за исключением линий, каналов и средств связи, принадлежащих дипломатическим представительствам, консульским учреждениям иностранных государств и представительствам международных организаций);\n5) безвозмездно получать от организаций информацию, необходимую для исполнения военнослужащими (сотрудниками) войск национальной гвардии служебных обязанностей, за исключением случаев, когда законодательством Российской Федерации установлен иной порядок получения соответствующей информации;\n6) осуществлять проверку у граждан документов, удостоверяющих их личность, при наличии данных о том, что у граждан имеется оружие, боеприпасы, взрывчатые вещества, специальные средства, производить личный досмотр граждан, досмотр их вещей, жилых и иных помещений, транспортных средств, плавучих средств (судов);\n7) задерживать граждан, нарушивших правила комендантского часа, установленные в соответствии с федеральным законодательством, до его окончания, а лиц, не имеющих при себе документов, удостоверяющих их личность, задерживать до установления их личности, но не более чем на срок, предусмотренный федеральным законодательством, с последующим их доставлением в полицию;\n8) принимать неотложные меры по спасению людей, охране имущества, оставшегося без присмотра, обеспечению охраны общественного порядка при чрезвычайных ситуациях и других чрезвычайных обстоятельствах, при обеспечении режима чрезвычайного положения, в том числе на объектах транспорта и транспортной инфраструктуры.\n2. Военнослужащим (сотрудникам) войск национальной гвардии в целях обеспечения режима военного положения, правового режима контртеррористической операции, а также участия в контртеррористической операции предоставляется право на применение мер и временных ограничений, предусмотренных соответственно федеральным законодательством о военном положении и о противодействии терроризму."],
["16","Обязанности федеральных органов исполнительной власти, органов исполнительной власти субъектов Российской Федерации, исполнительно-распорядительных органов муниципальных образований и их должностных лиц, железнодорожных перевозчиков, перевозчиков на внутреннем водном транспорте и воздушном транспорте по содействию войскам национальной гвардии в выполнении возложенных на них задач","Глава 2. Полномочия войск национальной гвардии","2023-08-04","Статья 16. Обязанности федеральных органов исполнительной власти, органов исполнительной власти субъектов Российской Федерации, исполнительно-распорядительных органов муниципальных образований и их должностных лиц, железнодорожных перевозчиков, перевозчиков на внутреннем водном транспорте и воздушном транспорте по содействию войскам национальной гвардии в выполнении возложенных на них задач\n1. Федеральные органы исполнительной власти и их должностные лица в пределах своих полномочий:\n1) предоставляют на бесплатной основе воздушным судам (кораблям, катерам, плавучим средствам (судам) войск национальной гвардии при выполнении ими задач по обеспечению режимов чрезвычайного положения, военного положения, правового режима контртеррористической операции, задач в условиях контртеррористической операции и других чрезвычайных ситуаций право на использование в первоочередном порядке воздушного (водного) пространства, посадку, стоянку, взлет, получение навигационной, метеорологической и иной информации, необходимой для обеспечения полетов (кораблевождения), в аэропортах, на аэродромах, посадочных площадках (в морских и речных портах, у причалов), находящихся в ведении федеральных органов исполнительной власти;\n2) осуществляют на платной основе заправку воздушных судов (кораблей, катеров, плавучих средств (судов) войск национальной гвардии, выполняющих возложенные на них задачи, горючим и смазочными материалами, обеспечение их водой и электроэнергией, а также запасными частями;\n3) представляют войскам национальной гвардии необходимую информацию в целях реализации возложенных на войска национальной гвардии полномочий. Порядок представления такой информации определяется совместными решениями уполномоченного федерального органа исполнительной власти и соответствующих федеральных органов исполнительной власти.\n2. Федеральный орган исполнительной власти, уполномоченный в области обороны, федеральный орган исполнительной власти, уполномоченный в области связи, федеральный орган исполнительной власти, уполномоченный в области транспорта, и другие федеральные органы исполнительной власти предоставляют войскам национальной гвардии на бесплатной основе линии, каналы и средства связи при выполнении ими задач по обеспечению режимов чрезвычайного положения, военного положения, правового режима контртеррористической операции, задач в условиях контртеррористической операции и других чрезвычайных ситуаций.\n3. Федеральный орган исполнительной власти, уполномоченный в области обороны:\n1) предоставляет войскам национальной гвардии воздушные, морские и речные суда, плавучие средства, вооружение, военную и специальную технику, продовольственное, вещевое и медицинское имущество при выполнении задач по обеспечению режимов чрезвычайного положения, военного положения, правового режима контртеррористической операции, задач в условиях контртеррористической операции и других чрезвычайных ситуаций; (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n2) осуществляет накопление и эшелонирование запасов вооружения, военной и специальной техники, технических средств, боеприпасов, горючего и смазочных материалов, запасных частей, продовольствия, вещевого, медицинского и другого имущества на базах, складах и в арсеналах Вооруженных Сил Российской Федерации для войск национальной гвардии на военное время; (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n3) оказывает помощь в ремонте и восстановлении поврежденных и вышедших из строя вооружения, военной и специальной техники войск национальной гвардии; (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n4) предоставляет в случае необходимости полигоны, учебные центры и другие объекты учебно-материальной базы для подготовки войск национальной гвардии к выполнению служебно-боевых задач;\n5) оказывает помощь в лечебных и лечебно-эвакуационных мероприятиях войск национальной гвардии.\n4. Железнодорожные перевозчики, перевозчики на внутреннем водном транспорте и воздушном транспорте:\n1) по заявкам органов управления войск национальной гвардии в первоочередном порядке за плату предоставляют обусловленное заявкой количество железнодорожного подвижного состава (контейнеров), мест в пассажирских поездах, морских и речных судах, воздушных судах в целях своевременного осуществления воинских и специальных железнодорожных перевозок, включая отправки воинских эшелонов (транспортов) и перевозки следующих самостоятельно военнослужащих (сотрудников) войск национальной гвардии (в том числе для осуществления внеплановых перевозок);\n2) предоставляют органам управления войск национальной гвардии необходимую информацию об осуществлении воинских и специальных железнодорожных перевозок, выполняемых по заявкам органов управления войск национальной гвардии, в том числе об отправке и продвижении воинских эшелонов (транспортов) и военнослужащих (сотрудников) войск национальной гвардии.\n5. Должностные лица органов управления на транспорте, военные коменданты, представители военно-транспортных органов федерального органа исполнительной власти, уполномоченного в области обороны, и органов специальных перевозок федерального органа исполнительной власти, уполномоченного в сфере внутренних дел, оказывают содействие в перевозке в первоочередном порядке военнослужащих (сотрудников) войск национальной гвардии при выполнении ими задач по обеспечению режимов чрезвычайного положения, военного положения, правового режима контртеррористической операции, задач в условиях контртеррористической операции и других чрезвычайных ситуаций, а также в перевозке указанных военнослужащих (сотрудников) при выполнении иных задач, возложенных на войска национальной гвардии.\n6. Федеральный орган исполнительной власти, уполномоченный в области управления государственным материальным резервом, осуществляет накопление и содержание запасов горючего и смазочных материалов, продовольствия и других материально-технических средств для войск национальной гвардии в государственном материальном резерве.\n7. Органы исполнительной власти субъектов Российской Федерации, исполнительно-распорядительные органы муниципальных образований (местные администрации) и их должностные лица оказывают содействие войскам национальной гвардии в выполнении возложенных на них задач, предоставляют в порядке, определенном Правительством Российской Федерации, войскам национальной гвардии здания (помещения), сооружения и земельные участки на период подготовки и выполнения ими служебно-боевых задач.\n8. (Часть утратила силу - Федеральный закон от 11.10.2018 № 364-ФЗ)"],
["17","Обеспечение полетов воздушных судов войск национальной гвардии","Глава 2. Полномочия войск национальной гвардии","2024-02-26","Статья 17. Обеспечение полетов воздушных судов войск национальной гвардии\nАэронавигационное обслуживание полетов воздушных судов войск национальной гвардии (организация воздушного движения, радиотехническое обеспечение полетов, обеспечение авиационной электросвязи, предоставление аэронавигационной и метеорологической информации, поиск и спасание) и светотехническое, инженерно-авиационное, аэродромное, аварийно-спасательное и другое обеспечение полетов таких воздушных судов осуществляются без взимания платы (за исключением полетов, связанных с коммерческими воздушными перевозками).\n(Статья в редакции Федерального закона от 26.02.2024 № 27-ФЗ)"],
["18","Право на применение физической силы, специальных средств, вооружения, военной и специальной техники и порядок их применения","Глава 3. Применение военнослужащими (сотрудниками) войск национальной гвардии физической силы, специальных средств, вооружения, военной и специальной техники","2023-08-04","Статья 18. Право на применение физической силы, специальных средств, вооружения, военной и специальной техники и порядок их применения\n(Наименование в редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n1. Военнослужащий (сотрудник) войск национальной гвардии имеет право на применение физической силы, специальных средств, вооружения, военной и специальной техники лично или в составе подразделения (группы), а командиры (начальники) имеют право отдавать приказы об их применении в случаях и порядке, которые предусмотрены федеральными конституционными законами, настоящим Федеральным законом и другими федеральными законами. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n2. Военнослужащий (сотрудник) войск национальной гвардии обязан проходить специальную подготовку, а также периодическую проверку на профессиональную пригодность к действиям в условиях, связанных с применением физической силы, специальных средств, вооружения, военной и специальной техники, и на умение оказывать первую помощь пострадавшим в результате их применения. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n3. Военнослужащий (сотрудник) войск национальной гвардии перед применением физической силы, специальных средств, оружия обязан сообщить лицам, в отношении которых предполагается применение физической силы, специальных средств, оружия, о том, что он является военнослужащим (сотрудником) войск национальной гвардии, предупредить их о своем намерении и предоставить им возможность и время для выполнения законных требований военнослужащего (сотрудника) войск национальной гвардии. В случае применения физической силы, специальных средств или оружия в составе подразделения (группы) указанное предупреждение делает один из военнослужащих (сотрудников) войск национальной гвардии, входящий в состав подразделения (группы).\n4. Военнослужащий (сотрудник) войск национальной гвардии имеет право не предупреждать о своем намерении применить физическую силу, специальные средства, оружие, если промедление в их применении создает непосредственную угрозу жизни или здоровью гражданина или военнослужащего (сотрудника) войск национальной гвардии либо может повлечь за собой иные тяжкие последствия, а также при отражении нападения на охраняемые объекты, специальные грузы, сооружения на коммуникациях и собственные объекты войск национальной гвардии.\n5. Военнослужащий (сотрудник) войск национальной гвардии при применении физической силы, специальных средств, вооружения, военной и специальной техники действует с учетом создавшейся обстановки, характера и степени опасности действий лиц, в отношении которых применяются физическая сила, специальные средства, вооружение, военная и специальная техника, характера и силы оказываемого ими сопротивления. При этом военнослужащий (сотрудник) войск национальной гвардии обязан стремиться к минимизации любого ущерба. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n6. Военнослужащий (сотрудник) войск национальной гвардии обязан оказать гражданину, получившему телесные повреждения в результате применения физической силы, специальных средств, вооружения, военной и специальной техники, первую помощь, а также принять меры по оказанию ему медицинской помощи в возможно короткий срок. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n7. О причинении гражданину ранений в результате применения военнослужащим (сотрудником) войск национальной гвардии физической силы, специальных средств, вооружения, военной и специальной техники в возможно короткий срок, но не более 24 часов уведомляются близкие родственники или близкие лица гражданина. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n8. О каждом случае причинения гражданину ранения либо наступления смерти гражданина в результате применения военнослужащим (сотрудником) войск национальной гвардии физической силы, специальных средств, вооружения, военной и специальной техники в возможно короткий срок, но не позднее 24 часов уведомляется прокурор. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n9. Военнослужащий (сотрудник) войск национальной гвардии обязан по возможности сохранить без изменения место совершения преступления, административного правонарушения, место происшествия, если в результате применения им физической силы, специальных средств, вооружения, военной и специальной техники гражданину причинено ранение либо наступила его смерть. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n10. О каждом случае применения физической силы, специальных средств, вооружения, военной и специальной техники, в результате которого причинен вред здоровью гражданина или причинен материальный ущерб гражданину (организации), военнослужащий (сотрудник) войск национальной гвардии обязан немедленно доложить непосредственному командиру (начальнику). (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n11. В составе подразделения (группы) военнослужащий (сотрудник) войск национальной гвардии применяет физическую силу, специальные средства, вооружение, военную и специальную технику в соответствии с федеральным законом, руководствуясь приказами и распоряжениями командира (начальника) этого подразделения (группы). (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n12. Превышение военнослужащим (сотрудником) войск национальной гвардии полномочий при применении физической силы, специальных средств, вооружения, военной и специальной техники влечет ответственность, установленную уголовным законодательством Российской Федерации. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n13. В состоянии необходимой обороны, в случае крайней необходимости или при задержании лица, совершившего преступление, военнослужащий (сотрудник) войск национальной гвардии при отсутствии у него необходимых специальных средств или оружия вправе использовать любые подручные средства.\n14. Военнослужащий (сотрудник) войск национальной гвардии не несет ответственность за вред, причиненный гражданам и организациям при применении физической силы, специальных средств, вооружения, военной и специальной техники, если применение физической силы, специальных средств, вооружения, военной и специальной техники осуществлялось по основаниям и в порядке, которые установлены федеральными конституционными законами, настоящим Федеральным законом и другими федеральными законами. Возмещение такого вреда осуществляется в соответствии с законодательством Российской Федерации. (В редакции федеральных законов от 05.12.2017 № 391-ФЗ, от 04.08.2023 № 446-ФЗ)"],
["19","Применение физической силы","Глава 3. Применение военнослужащими (сотрудниками) войск национальной гвардии физической силы, специальных средств, вооружения, военной и специальной техники","2023-08-04","Статья 19. Применение физической силы\n1. Военнослужащий (сотрудник) войск национальной гвардии имеет право лично или в составе подразделения (группы) применять физическую силу, в том числе боевые приемы борьбы, если несиловые способы не обеспечивают выполнения возложенных на войска национальной гвардии задач, в следующих случаях:\n1) для пресечения преступлений и административных правонарушений;\n2) для задержания и доставления в полицию лиц, подозреваемых в совершении преступления, а также лиц, в отношении которых имеется повод к возбуждению дела об административном правонарушении;\n3) для преодоления противодействия законным требованиям военнослужащего (сотрудника) войск национальной гвардии.\n2. Военнослужащий (сотрудник) войск национальной гвардии имеет право применять физическую силу во всех случаях, когда настоящим Федеральным законом разрешено применение специальных средств, вооружения, военной и специальной техники. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)"],
["20","Применение специальных средств","Глава 3. Применение военнослужащими (сотрудниками) войск национальной гвардии физической силы, специальных средств, вооружения, военной и специальной техники","2023-08-04","Статья 20. Применение специальных средств\n1. Военнослужащий (сотрудник) войск национальной гвардии имеет право лично или в составе подразделения (группы) применять специальные средства в следующих случаях:\n1) для отражения нападения на гражданина или военнослужащего (сотрудника) войск национальной гвардии;\n2) для пресечения преступления или административного правонарушения;\n3) для пресечения сопротивления, оказываемого военнослужащему (сотруднику) войск национальной гвардии;\n4) для задержания лица, застигнутого при совершении преступления и пытающегося скрыться;\n5) для задержания лица, если это лицо может оказать вооруженное сопротивление или воспрепятствовать исполнению военнослужащим (сотрудником) войск национальной гвардии возложенных на него обязанностей;\n6) для доставления в полицию, а также в целях пресечения попытки побега в случае оказания лицом сопротивления военнослужащему (сотруднику) войск национальной гвардии, причинения вреда окружающим или себе;\n7) для освобождения заложников, захваченных зданий, помещений, сооружений, транспортных средств, плавучих средств (судов) и земельных участков;\n8) для пресечения массовых беспорядков и иных противоправных действий, нарушающих движение транспорта, работу средств связи и организаций;\n9) для остановки транспортного средства, плавучего средства (судна), если лицо, управляющее этим транспортным средством, плавучим средством (судном), не выполнило законное требование сотрудника полиции или военнослужащего (сотрудника) войск национальной гвардии об остановке;\n10) для защиты охраняемых войсками национальной гвардии объектов, сооружений, блокирования движения групп, совершающих противоправные действия;\n11) для отражения группового или вооруженного нападения на охраняемые войсками национальной гвардии объекты, специальные грузы, сооружения на коммуникациях, а также собственные объекты войск национальной гвардии;\n12) для пресечения функционирования беспилотных аппаратов в целях, предусмотренных пунктом 33 части 1 статьи 9 настоящего Федерального закона. (Дополнение пунктом - Федеральный закон от 02.12.2019 № 404-ФЗ) (В редакции Федерального закона от 04.08.2023 № 440-ФЗ)\n2. Военнослужащий (сотрудник) войск национальной гвардии имеет право применять следующие специальные средства:\n1) палки специальные - в случаях, предусмотренных пунктами 1 - 5, 7, 8, 10 и 11 части 1 настоящей статьи;\n2) средства раздражающего действия - в случаях, предусмотренных пунктами 1 - 5, 7, 8, 10 и 11 части 1 настоящей статьи;\n3) средства ограничения подвижности - в случаях, предусмотренных пунктами 3, 4 и 6 части 1 настоящей статьи. При отсутствии средств ограничения подвижности военнослужащий (сотрудник) войск национальной гвардии вправе использовать подручные средства связывания;\n4) водометы - в случаях, предусмотренных пунктами 7, 8 и 11 части 1 настоящей статьи;\n5) специальные окрашивающие и маркирующие средства - в случаях, предусмотренных пунктом 10 части 1 настоящей статьи;\n6) ударно-шоковые средства - в случаях, предусмотренных пунктами 1, 4, 7, 8 и 11 части 1 настоящей статьи;\n7) электрошоковые устройства - в случаях, предусмотренных пунктами 1 - 5, 7, 8 и 11 части 1 настоящей статьи;\n8) светошоковые устройства - в случаях, предусмотренных пунктами 1 - 5, 7, 8 и 11 части 1 настоящей статьи;\n9) световые и акустические специальные средства - в случаях, предусмотренных пунктами 5, 7, 8, 10 и 11 части 1 настоящей статьи;\n10) светозвуковые средства отвлекающего воздействия - в случаях, предусмотренных пунктами 1, 4, 6 - 8 и 11 части 1 настоящей статьи;\n11) средства разрушения преград - в случаях, предусмотренных пунктами 5 и 7 части 1 настоящей статьи;\n12) средства принудительной остановки транспорта - в случаях, предусмотренных пунктами 9 - 11 части 1 настоящей статьи;\n13) средства сковывания движения - в случаях, предусмотренных пунктами 1 - 5 части 1 настоящей статьи;\n14) средства защиты охраняемых объектов (территорий), блокирования движения групп граждан, совершающих противоправные действия, - в случаях, предусмотренных пунктами 10 и 11 части 1 настоящей статьи;\n15) служебных животных - в случаях, предусмотренных пунктами 1 - 7, 10 и 11 части 1 настоящей статьи;\n16) специальные технические средства противодействия беспилотным аппаратам - в случаях, предусмотренных пунктом 12 части 1 настоящей статьи. (Дополнение пунктом - Федеральный закон от 02.12.2019 № 404-ФЗ) (В редакции Федерального закона от 04.08.2023 № 440-ФЗ)\n3. Военнослужащий (сотрудник) войск национальной гвардии имеет право применять специальные средства во всех случаях, когда настоящим Федеральным законом разрешено применение оружия.\n4. Запрещается применять специальные средства в отношении женщин с видимыми признаками беременности, лиц с явными признаками инвалидности и малолетних лиц, за исключением случаев оказания указанными лицами вооруженного сопротивления, совершения группового или иного нападения, угрожающего жизни или здоровью граждан или военнослужащего (сотрудника) войск национальной гвардии.\n5. Не допускается применение водометов при температуре воздуха ниже нуля градусов Цельсия, средств принудительной остановки транспорта в отношении транспортных средств, предназначенных для перевозки пассажиров (при наличии пассажиров), транспортных средств, принадлежащих дипломатическим представительствам, консульским учреждениям иностранных государств, представительствам международных организаций, а также в отношении мотоциклов, мотоколясок, мотороллеров и мопедов; на горных дорогах или участках дорог с ограниченной видимостью; на железнодорожных переездах, мостах, путепроводах, эстакадах, в туннелях.\n6. Иные ограничения, связанные с применением военнослужащим (сотрудником) войск национальной гвардии специальных средств, могут быть установлены руководителем уполномоченного федерального органа исполнительной власти."],
["21","Применение оружия","Глава 3. Применение военнослужащими (сотрудниками) войск национальной гвардии физической силы, специальных средств, вооружения, военной и специальной техники","2023-08-04","Статья 21. Применение оружия\n1. Военнослужащий (сотрудник) войск национальной гвардии имеет право лично или в составе подразделения (группы) применять оружие в следующих случаях:\n1) для защиты граждан, военнослужащих (сотрудников) войск национальной гвардии, должностных лиц государственных органов и органов местного самоуправления;\n2) для пресечения попытки завладеть вооружением, военной, специальной и иной техникой, собственными объектами войск национальной гвардии; (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n3) для освобождения заложников, пресечения террористических и иных преступных посягательств;\n4) для задержания лиц, застигнутых при совершении деяния, содержащего признаки тяжкого или особо тяжкого преступления против жизни, здоровья или собственности, и пытающихся скрыться либо оказывающих вооруженное сопротивление;\n5) для производства предупредительного выстрела, а также для подачи сигнала тревоги или вызова помощи путем производства выстрела вверх или в ином безопасном направлении;\n6) для пресечения попыток лиц незаконно проникнуть на территории (акватории) (покинуть территории (акватории) охраняемых войсками национальной гвардии объектов, а также постов и других мест несения войсками национальной гвардии боевой службы, если невозможно пресечь эти попытки иным способом;\n7) для остановки транспортного средства, плавучего средства (судна) путем его повреждения, если водитель (капитан) отказывается остановиться, несмотря на законные требования сотрудников полиции или военнослужащих (сотрудников) войск национальной гвардии;\n8) для обезвреживания животного, угрожающего жизни или здоровью граждан или военнослужащего (сотрудника) войск национальной гвардии;\n9) для разрушения запирающих устройств, элементов и конструкций, препятствующих проникновению в жилые и иные принадлежащие физическим лицам помещения и на принадлежащие им земельные участки, на территории и в помещения организаций независимо от форм собственности по основаниям, предусмотренным статьей 12 настоящего Федерального закона;\n10) для пресечения функционирования беспилотных аппаратов в целях, предусмотренных пунктом 33 части 1 статьи 9 настоящего Федерального закона. (Дополнение пунктом - Федеральный закон от 02.12.2019 № 404-ФЗ) (В редакции Федерального закона от 04.08.2023 № 440-ФЗ)\n2. (Часть утратила силу - Федеральный закон от 04.08.2023 № 446-ФЗ)\n3. Военнослужащий (сотрудник) войск национальной гвардии имеет право применять оружие без предупреждения при отражении нападения с использованием оружия, боевой и специальной техники, транспортных средств, летательных аппаратов, морских или речных судов.\n4. Запрещается применять оружие в отношении женщин с видимыми признаками беременности, лиц с явными признаками инвалидности и малолетних лиц, за исключением случаев оказания указанными лицами вооруженного сопротивления, совершения группового или иного нападения, угрожающего жизни или здоровью граждан или военнослужащего (сотрудника) войск национальной гвардии.\n5. Военнослужащий (сотрудник) войск национальной гвардии не имеет права применять оружие при значительном скоплении людей, если в результате его применения могут пострадать случайные лица, за исключением случаев применения оружия в целях предотвращения (пресечения) террористического акта, освобождения заложников, отражения группового или вооруженного нападения на важные государственные объекты, специальные грузы, сооружения на коммуникациях, охраняемые войсками национальной гвардии, и на собственные объекты войск национальной гвардии.\n6. Вооруженным сопротивлением или вооруженным нападением признается сопротивление или нападение, совершаемые с использованием оружия любого вида, либо предметов, конструктивно схожих с оружием или внешне не отличимых от него, либо предметов, веществ и механизмов, при помощи которых могут быть причинены тяжкий вред здоровью или смерть."],
["22","Применение оружия, иного вооружения, военной и специальной техники","Глава 3. Применение военнослужащими (сотрудниками) войск национальной гвардии физической силы, специальных средств, вооружения, военной и специальной техники","2023-08-04","Статья 22. Применение оружия, иного вооружения, военной и специальной техники\n(Наименование в редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n1. Оружие, иное вооружение, военная и специальная техника, состоящие на вооружении войск национальной гвардии, применяются в следующих случаях: (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n1) для освобождения заложников, захваченных охраняемых войсками национальной гвардии объектов, специальных грузов, сооружений на коммуникациях, собственных объектов войск национальной гвардии, вооружения, военной, специальной и иной техники; (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n2) для защиты граждан, военнослужащих (сотрудников) войск национальной гвардии, должностных лиц государственных органов и органов местного самоуправления;\n3) для остановки транспортного средства, плавучего средства (судна) путем его повреждения, если водитель (капитан) отказывается остановиться, несмотря на законные требования сотрудников полиции или военнослужащих (сотрудников) войск национальной гвардии, и пытается скрыться, создавая угрозу жизни и здоровью граждан;\n4) для отражения группового или вооруженного нападения (в том числе с использованием транспортных средств) на охраняемые войсками национальной гвардии объекты, специальные грузы, сооружения на коммуникациях, собственные объекты войск национальной гвардии, на помещения, занимаемые государственными органами, органами местного самоуправления, организациями и общественными объединениями;\n5) для пресечения деятельности незаконных вооруженных формирований;\n6) для подавления сопротивления вооруженных лиц, отказывающихся выполнить законные требования военнослужащего (сотрудника) войск национальной гвардии о прекращении противоправных действий и сдаче имеющихся у этих лиц вооружения, боеприпасов, взрывчатых веществ, специальных средств, военной и специальной техники; (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n7) для спасения жизни граждан и (или) их имущества, обеспечения безопасности граждан или общественной безопасности при массовых беспорядках и чрезвычайных ситуациях;\n8) для пресечения функционирования беспилотных аппаратов в целях, предусмотренных пунктом 33 части 1 статьи 9 настоящего Федерального закона. (Дополнение пунктом - Федеральный закон от 02.12.2019 № 404-ФЗ) (В редакции Федерального закона от 04.08.2023 № 440-ФЗ)\n2. В случаях, предусмотренных пунктами 5, 7, 8, 10 и 11 части 1 статьи 20 настоящего Федерального закона, по указанию соответствующего командира (начальника) - от командира воинской части войск национальной гвардии, ему равных и выше - или его заместителя могут применяться бронемашины с последующим обязательным уведомлением прокурора в течение 24 часов с момента их применения."],
["23","Гарантии личной безопасности военнослужащих (сотрудников) войск национальной гвардии и членов их семей","Глава 3. Применение военнослужащими (сотрудниками) войск национальной гвардии физической силы, специальных средств, вооружения, военной и специальной техники","","Статья 23. Гарантии личной безопасности военнослужащих (сотрудников) войск национальной гвардии и членов их семей\n1. Военнослужащий (сотрудник) войск национальной гвардии имеет право обнажить оружие и привести его в готовность, если в создавшейся обстановке могут возникнуть основания для его применения, предусмотренные статьей 21 настоящего Федерального закона.\n2. При попытке лица, задерживаемого военнослужащим (сотрудником) войск национальной гвардии с приведенным в готовность оружием, приблизиться к нему с обнаженным оружием либо с предметами, конструктивно схожими с оружием или внешне не отличимыми от него, в том числе с помощью которых военнослужащему (сотруднику) войск национальной гвардии может быть нанесено телесное повреждение, сократив при этом указанное военнослужащим (сотрудником) расстояние, а также при попытке прикоснуться к его оружию военнослужащий (сотрудник) войск национальной гвардии имеет право применить оружие в соответствии с частью 3 статьи 21 настоящего Федерального закона.\n3. В интересах личной безопасности военнослужащих (сотрудников) войск национальной гвардии и членов их семей не допускается распространение в публичных выступлениях, в средствах массовой информации сведений о местах дислокации или о передислокации органов управления войсками национальной гвардии, объединений, соединений, воинских частей войск национальной гвардии, а также обеспечивается конфиденциальность сведений о военнослужащих (сотрудниках) войск национальной гвардии и членах их семей.\n4. Порядок предоставления информации об органах управления войсками национальной гвардии, объединениях, соединениях, воинских частях, подразделениях и организациях войск национальной гвардии и их деятельности, а также о военнослужащих (сотрудниках) определяется руководителем уполномоченного федерального органа исполнительной власти.\n5. Военнослужащий (сотрудник) войск национальной гвардии имеет право на ношение и хранение оружия и специальных средств. Порядок выдачи, ношения и хранения оружия и специальных средств определяется руководителем уполномоченного федерального органа исполнительной власти."],
["24","Военная служба, служба в войсках национальной гвардии. Комплектование войск национальной гвардии личным составом","Глава 4. Личный состав войск национальной гвардии","2026-03-08","Статья 24. Военная служба, служба в войсках национальной гвардии. Комплектование войск национальной гвардии личным составом\n1. В войсках национальной гвардии предусматриваются военная служба, служба в войсках национальной гвардии Российской Федерации, государственная гражданская служба.\n2. Личный состав войск национальной гвардии включает в себя военнослужащих, сотрудников и лиц гражданского персонала (федеральных государственных гражданских служащих и работников) войск национальной гвардии.\n3. Комплектование войск национальной гвардии осуществляется в соответствии с законодательством Российской Федерации:\n1) военнослужащими - путем призыва граждан Российской Федерации на военную службу по экстерриториальному принципу и путем добровольного поступления граждан Российской Федерации на военную службу;\n2) сотрудниками - путем добровольного поступления граждан Российской Федерации на службу в войска национальной гвардии и путем поступления граждан Российской Федерации на службу в войска национальной гвардии по мобилизации; (В редакции Федерального закона от 04.08.2023 № 436-ФЗ)\n3) федеральными государственными гражданскими служащими;\n4) работниками.\n4. Военнослужащие (сотрудники) войск национальной гвардии должны иметь необходимую профессиональную, правовую и физическую подготовку, умело владеть специальными средствами, закрепленными за ними вооружением, военной и специальной техникой. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n5. Военнослужащие (сотрудники) войск национальной гвардии подлежат обязательной государственной дактилоскопической регистрации и обязательной государственной геномной регистрации в соответствии с законодательством Российской Федерации. (В редакции Федерального закона от 08.03.2026 № 52-ФЗ)\n6. Должностные лица органов управления войсками национальной гвардии, объединений, соединений, воинских частей и организаций войск национальной гвардии участвуют в отборе граждан Российской Федерации, подлежащих призыву на военную службу, для службы в войсках национальной гвардии, а также направлению по мобилизации в войска национальной гвардии для прохождения службы на должностях, по которым предусмотрено присвоение специальных званий полиции. (В редакции Федерального закона от 04.08.2023 № 436-ФЗ)\n7. Отбор граждан Российской Федерации, подлежащих призыву на военную службу, для службы в войсках национальной гвардии осуществляется по согласованию с федеральным органом исполнительной власти, уполномоченным в области безопасности.\n8. Войскам национальной гвардии предоставляется право самостоятельно в порядке, определяемом руководителем уполномоченного федерального органа исполнительной власти, осуществлять отбор (в том числе на конкурсной основе) кандидатов для поступления на военную службу (на службу) по контракту в войска национальной гвардии и определять соответствие кандидатов требованиям, предъявляемым к гражданам Российской Федерации, поступающим на военную службу (на службу) по контракту, в том числе путем психологических и психофизиологических исследований (обследований) с применением специализированных технических устройств, не наносящих ущерба жизни и здоровью людей и не причиняющих вреда окружающей среде. (В редакции Федерального закона от 29.07.2018 № 264-ФЗ)\n8.1. Граждане Российской Федерации не могут быть приняты на военную службу (на службу), федеральную государственную гражданскую службу или работу в войска национальной гвардии, а военнослужащие (сотрудники) и лица гражданского персонала войск национальной гвардии могут быть уволены с военной службы (со службы), федеральной государственной гражданской службы или работы по основаниям, предусмотренным законодательством Российской Федерации, а также в случае отказа от прохождения проверок, предусмотренных настоящим Федеральным законом, непредставления информации, подлежащей обязательному представлению в соответствии с настоящим Федеральным законом, либо представления заведомо ложной информации. (Дополнение частью - Федеральный закон от 18.03.2020 № 64-ФЗ)\n9. Медицинское освидетельствование граждан, поступающих на военную службу по контракту, на службу в войска национальной гвардии, осуществляется в медицинских организациях уполномоченного федерального органа исполнительной власти либо федерального органа исполнительной власти в сфере внутренних дел за счет средств, предусмотренных в федеральном бюджете соответственно уполномоченному федеральному органу исполнительной власти, федеральному органу исполнительной власти в сфере внутренних дел на эти цели.\n10. Перечни воинских должностей, которые могут замещаться военнослужащими женского пола, гражданским персоналом войск национальной гвардии (за исключением воинских должностей, для которых штатом предусмотрены воинские звания высших офицеров, а также воинских должностей, которые могут замещаться федеральными государственными гражданскими служащими), устанавливаются руководителем уполномоченного федерального органа исполнительной власти.\n11. Военнослужащим (сотрудникам) и гражданскому персоналу войск национальной гвардии выдаются служебные удостоверения, подтверждающие личность, должность, права и полномочия, предоставленные военнослужащему (сотруднику) войск национальной гвардии. Образцы, категория лиц и порядок выдачи служебных удостоверений утверждаются уполномоченным федеральным органом исполнительной власти."],
["24.1","Меры по обеспечению собственной безопасности войск национальной гвардии","Глава 4. Личный состав войск национальной гвардии","2023-08-04","Статья 24.1. Меры по обеспечению собственной безопасности войск национальной гвардии\n1. Граждане Российской Федерации, поступающие на военную службу (на службу), федеральную государственную гражданскую службу или работу в войска национальной гвардии, военнослужащие (сотрудники) и лица гражданского персонала войск национальной гвардии проходят проверку, которая связана с обеспечением собственной безопасности войск национальной гвардии, в том числе с применением технических и иных устройств, не наносящих ущерба жизни и здоровью людей и не причиняющих вреда окружающей среде, в случаях, порядке и сроки, которые определяются руководителем уполномоченного федерального органа исполнительной власти.\n2. Граждане Российской Федерации, поступающие на военную службу (на службу), федеральную государственную гражданскую службу или работу в войска национальной гвардии, военнослужащие (сотрудники) и лица гражданского персонала войск национальной гвардии обязаны представлять информацию, относящуюся к обеспечению собственной безопасности войск национальной гвардии, в соответствии с перечнем, в случаях и порядке, которые определяются руководителем уполномоченного федерального органа исполнительной власти.\n3. Согласие граждан Российской Федерации, поступающих на военную службу (на службу), федеральную государственную гражданскую службу или работу в войска национальной гвардии, военнослужащих (сотрудников) и лиц гражданского персонала войск национальной гвардии на прохождение в период военной службы (службы, работы) проверки и представление информации, указанных в частях 1 и 2 настоящей статьи, закрепляется соответственно в заявлении о приеме на военную службу (на службу, работу), контракте о прохождении военной службы, контракте о прохождении службы в войсках национальной гвардии, служебном контракте, трудовом договоре.\n4. Личному составу войск национальной гвардии запрещается размещать в средствах массовой информации, в информационно-телекоммуникационной сети \"Интернет\" информацию (в том числе фото-, видеоматериалы и другие материалы) о себе, других военнослужащих, сотрудниках, гражданском персонале войск национальной гвардии, в том числе уволенных с военной службы (службы), членах их семей или их родителях, позволяющую установить место нахождения указанных лиц в определенный период времени другим лицам, информацию, позволяющую раскрыть ведомственную принадлежность к войскам национальной гвардии, а также информацию о своей служебной деятельности, деятельности войск национальной гвардии, за исключением случаев, предусмотренных нормативными правовыми актами Российской Федерации, нормативными правовыми актами уполномоченного федерального органа исполнительной власти. (Дополнение частью - Федеральный закон от 04.08.2023 № 436-ФЗ)\n(Дополнение статьей - Федеральный закон от 18.03.2020 № 64-ФЗ)"],
["24.2","Присяга сотрудника войск национальной гвардии","Глава 4. Личный состав войск национальной гвардии","2020-07-20","Статья 24.2. Присяга сотрудника войск национальной гвардии\n1. Сотрудник, впервые поступивший на службу в войска национальной гвардии, приводится к Присяге сотрудника войск национальной гвардии. Приведение к Присяге осуществляется в торжественной обстановке перед Государственным флагом Российской Федерации.\n2. Текст Присяги сотрудника войск национальной гвардии:\n\"Я (фамилия, имя, отчество), поступая на службу в войска национальной гвардии, торжественно присягаю на верность Российской Федерации и ее народу!\nКлянусь при осуществлении полномочий сотрудника войск национальной гвардии:\nуважать и защищать права и свободы человека и гражданина, свято соблюдать Конституцию Российской Федерации и федеральные законы;\nбыть мужественным, честным и бдительным, не щадить своих сил в борьбе с преступностью;\nдостойно исполнять свой служебный долг и возложенные на меня обязанности по обеспечению безопасности, законности и правопорядка, хранить государственную и служебную тайну.\nСлужу России, служу Закону!\"\n3. Порядок приведения к Присяге сотрудника войск национальной гвардии устанавливается уполномоченным федеральным органом исполнительной власти.\n(Дополнение статьей - Федеральный закон от 20.07.2020 № 235-ФЗ)"],
["24.3","Возникновение и изменение правоотношений на службе в период мобилизации","Глава 4. Личный состав войск национальной гвардии","2023-08-04","Статья 24.3. Возникновение и изменение правоотношений на службе в период мобилизации\nОсобенности поступления на службу граждан, направленных по мобилизации в войска национальной гвардии для прохождения службы на должностях, по которым предусмотрено присвоение специальных званий полиции, прохождения ими службы и увольнения со службы определяются Президентом Российской Федерации.\n(Дополнение статьей - Федеральный закон от 04.08.2023 № 436-ФЗ)"],
["25","Подготовка кадров для войск национальной гвардии","Глава 4. Личный состав войск национальной гвардии","2018-07-29","Статья 25. Подготовка кадров для войск национальной гвардии\n1. Подготовка кадров для войск национальной гвардии осуществляется путем:\n1) обучения в соответствии с федеральным законом по образовательным программам:\nа) основного общего и среднего общего образования, интегрированным с дополнительными общеразвивающими программами, имеющими целью подготовку несовершеннолетних обучающихся к военной или иной государственной службе;\nб) среднего профессионального образования;\nв) высшего образования;\nг) дополнительного профессионального образования;\nд) профессионального обучения;\n2) профессионально-должностной, командирской и боевой подготовки военнослужащих;\n3) профессиональной служебной и физической подготовки сотрудников.\n2. Подготовка кадров для войск национальной гвардии и их дополнительное профессиональное образование осуществляются в федеральных государственных организациях, осуществляющих образовательную деятельность и находящихся в ведении войск национальной гвардии. Подготовка кадров для войск национальной гвардии в военных образовательных организациях высшего образования Вооруженных Сил Российской Федерации и образовательных организациях высшего образования федерального органа исполнительной власти в сфере внутренних дел осуществляется за счет бюджетных ассигнований, предусматриваемых в федеральном бюджете уполномоченному федеральному органу исполнительной власти на эти цели.\n3. Подготовка кадров для войск национальной гвардии в соответствии с пунктом 1 части 1 настоящей статьи осуществляется за счет бюджетных ассигнований, предусматриваемых в федеральном бюджете уполномоченному федеральному органу исполнительной власти на эти цели.\n4. Дополнительное профессиональное образование военнослужащих (сотрудников) войск национальной гвардии осуществляется в организациях, осуществляющих образовательную деятельность.\n5. Порядок организации дополнительного профессионального образования военнослужащих (сотрудников) войск национальной гвардии, в том числе формы обучения и сроки освоения дополнительных профессиональных программ, устанавливается уполномоченным федеральным органом исполнительной власти.\n6. Военнослужащий (сотрудник) войск национальной гвардии, проходящий военную службу (службу) по контракту и имеющий высшее образование, может быть с его согласия направлен на обучение по очно-заочной или заочной форме для получения высшего образования по другой специальности или другому направлению подготовки в порядке, определяемом уполномоченным федеральным органом исполнительной власти.\n7. Военнослужащий (сотрудник) войск национальной гвардии может получать дополнительное профессиональное образование за пределами территории Российской Федерации на основании международных договоров Российской Федерации.\n8. Профессиональная служебная и физическая подготовка сотрудников, профессионально-должностная, командирская и боевая подготовка военнослужащих осуществляются по месту военной службы (службы) военнослужащего (сотрудника) войск национальной гвардии.\n9. Подготовка военнослужащих и сотрудников войск национальной гвардии может осуществляться в учебных воинских частях (центрах, учебных подразделениях) войск национальной гвардии, а также в образовательных организациях, учебных подразделениях (центрах) других федеральных органов исполнительной власти (на договорной основе). Подготовка прапорщиков (мичманов) также может осуществляться в школах прапорщиков войск национальной гвардии и в учебных воинских частях (центрах, учебных подразделениях) других федеральных органов исполнительной власти (на договорной основе). (В редакции Федерального закона от 29.07.2018 № 264-ФЗ)"],
["26","Порядок выполнения военнослужащими (сотрудниками) войск национальной гвардии возложенных на них задач","Глава 5. Гарантии правовой и социальной защиты военнослужащих (сотрудников) войск национальной гвардии","2018-07-29","Статья 26. Порядок выполнения военнослужащими (сотрудниками) войск национальной гвардии возложенных на них задач\n1. Порядок выполнения военнослужащими (сотрудниками) войск национальной гвардии возложенных на них задач, порядок и условия несения ими боевой службы, выполнения служебно-боевых (оперативно-служебных, служебных, боевых) задач, должностные и специальные обязанности военнослужащих (сотрудников) войск национальной гвардии и порядок их исполнения определяются руководителем уполномоченного федерального органа исполнительной власти в соответствии с федеральными конституционными законами, настоящим Федеральным законом, другими федеральными законами, нормативными правовыми актами Президента Российской Федерации, а также иными нормативными правовыми актами Российской Федерации. (В редакции Федерального закона от 29.07.2018 № 264-ФЗ)\n2. Военнослужащие (сотрудники) войск национальной гвардии при несении боевой службы, выполнении служебно-боевых (оперативно-служебных, служебных, боевых) задач являются представителями власти и находятся под защитой государства в соответствии с законодательством Российской Федерации. Никто, за исключением государственных органов и должностных лиц, уполномоченных на то федеральными законами, не вправе вмешиваться в их служебную деятельность.\n3. Продолжительность несения боевой службы, выполнения служебно-боевых задач военнослужащими войск национальной гвардии определяется временем фактического нахождения военнослужащего в составе караула, гарнизона, заставы, войскового наряда, а также в составе воинских частей (подразделений), привлекаемых для выполнения возложенных на войска национальной гвардии задач.\n4. Воспрепятствование исполнению военнослужащим (сотрудником) войск национальной гвардии служебных обязанностей, его оскорбление, сопротивление ему, насилие или угроза применения насилия по отношению к нему в связи с исполнением указанным военнослужащим (сотрудником) служебных обязанностей влечет за собой ответственность, предусмотренную законодательством Российской Федерации.\n5. Защита жизни и здоровья, чести и достоинства, а также имущества военнослужащего (сотрудника) войск национальной гвардии и членов его семьи от преступных посягательств в связи с исполнением им служебных обязанностей осуществляется в порядке, предусмотренном законодательством Российской Федерации.\n6. При исполнении военнослужащим (сотрудником) войск национальной гвардии служебно-боевых (оперативно-служебных, служебных, боевых) задач не допускаются его привод, задержание, личный досмотр и досмотр его вещей, а также досмотр личного и используемого им транспорта, плавучих средств (судов) без официального представителя войск национальной гвардии или решения суда.\n7. Сведения о военнослужащих (сотрудниках) войск национальной гвардии, выполнявших (выполняющих) специальные задания по противодействию терроризму, обеспечению безопасности лиц, в отношении которых принято решение о применении мер государственной защиты, составляют государственную тайну.\n8. Срок привлечения военнослужащих (сотрудников) войск национальной гвардии к выполнению задач по обеспечению режима чрезвычайного положения, правового режима контртеррористической операции, задач в условиях контртеррористической операции не должен превышать три месяца.\n9. При выполнении задач по обеспечению режима чрезвычайного положения, правового режима контртеррористической операции и задач в условиях контртеррористической операции военнослужащим (сотрудникам) войск национальной гвардии выплачиваются надбавки, производятся дополнительные денежные выплаты в порядке и размерах, которые установлены федеральными законами, нормативными правовыми актами Президента Российской Федерации, Правительства Российской Федерации, а также нормативными правовыми актами уполномоченного федерального органа исполнительной власти."],
["27","Предоставление отдельным категориям военнослужащих войск национальной гвардии жилых помещений","Глава 5. Гарантии правовой и социальной защиты военнослужащих (сотрудников) войск национальной гвардии","","Статья 27. Предоставление отдельным категориям военнослужащих войск национальной гвардии жилых помещений\n1. Организации, важные государственные объекты, и (или) специальные грузы, и (или) сооружения на коммуникациях которых подлежат охране войсками национальной гвардии в соответствии с перечнями, утвержденными Правительством Российской Федерации, обязаны:\n1) обеспечивать военнослужащих войск национальной гвардии, проходящих военную службу по контракту в воинских частях, выполняющих задачи по охране важных государственных объектов, и (или) специальных грузов, и (или) сооружений на коммуникациях, и не имеющих жилого помещения в населенном пункте по месту военной службы, а также проживающих совместно с ними членов их семей на период прохождения военной службы в этих воинских частях служебными жилыми помещениями или жилыми помещениями в общежитии, относящимися к жилым помещениям специализированного жилищного фонда и находящимися в хозяйственном ведении или оперативном управлении данных организаций;\n2) размещать военнослужащих войск национальной гвардии, проходящих военную службу по призыву в воинских частях, выполняющих задачи по охране важных государственных объектов, и (или) специальных грузов, и (или) сооружений на коммуникациях, в порядке, определяемом Правительством Российской Федерации.\n2. Организации, важные государственные объекты, и (или) специальные грузы, и (или) сооружения на коммуникациях которых подлежат охране войсками национальной гвардии в соответствии с перечнями, утвержденными Правительством Российской Федерации, при отсутствии жилых помещений специализированного жилищного фонда обязаны предоставлять военнослужащим войск национальной гвардии, проходящим военную службу по контракту в воинских частях, выполняющих задачи по охране важных государственных объектов, и (или) специальных грузов, и (или) сооружений на коммуникациях, не обеспеченным жилыми помещениями в порядке, установленном частью 1 настоящей статьи, а также проживающим совместно с ними членам их семей на период прохождения военной службы в этих воинских частях на условиях безвозмездного пользования жилые помещения, находящиеся в собственности данных организаций либо арендованные ими за счет средств от осуществления основной и (или) предпринимательской деятельности.\n3. Военнослужащим войск национальной гвардии, проходящим военную службу по контракту в воинских частях, выполняющих задачи по охране важных государственных объектов, и (или) специальных грузов, и (или) сооружений на коммуникациях, на период прохождения военной службы в этих воинских частях, а также членам их семей при невозможности предоставления им жилых помещений в соответствии с частями 1 и 2 настоящей статьи предоставляется служебное жилое помещение или жилое помещение в общежитии, относящиеся к жилым помещениям специализированного жилищного фонда, формируемого уполномоченным федеральным органом исполнительной власти за счет бюджетных ассигнований, предусматриваемых в федеральном бюджете указанному федеральному органу исполнительной власти на эти цели.\n4. В случае отсутствия жилых помещений, указанных в части 3 настоящей статьи, воинские части арендуют жилые помещения для обеспечения военнослужащих и совместно проживающих с ними членов их семей или по желанию военнослужащих ежемесячно выплачивают им денежную компенсацию за наем (поднаем) жилых помещений в порядке и размерах, которые определяются Правительством Российской Федерации, с компенсацией понесенных воинской частью расходов организациями, важные государственные объекты, и (или) специальные грузы, и (или) сооружения на коммуникациях которых подлежат охране войсками национальной гвардии в соответствии с перечнями, утвержденными Правительством Российской Федерации."],
["28","Медицинское обеспечение военнослужащих (сотрудников) войск национальной гвардии, граждан Российской Федерации, уволенных с военной службы (службы), членов их семей и лиц, находящихся на иждивении сотрудников (граждан Российской Федерации, уволенных со службы в войсках национальной гвардии)","Глава 5. Гарантии правовой и социальной защиты военнослужащих (сотрудников) войск национальной гвардии","2018-07-29","Статья 28. Медицинское обеспечение военнослужащих (сотрудников) войск национальной гвардии, граждан Российской Федерации, уволенных с военной службы (службы), членов их семей и лиц, находящихся на иждивении сотрудников (граждан Российской Федерации, уволенных со службы в войсках национальной гвардии)\n(Наименование в редакции Федерального закона от 29.07.2018 № 264-ФЗ)\n1. Военнослужащие (сотрудники) войск национальной гвардии, граждане Российской Федерации, уволенные с военной службы из внутренних войск, уволенные с военной службы (службы) в войсках национальной гвардии, члены их семей и лица, находящиеся на иждивении сотрудников (граждан Российской Федерации, уволенных со службы в войсках национальной гвардии), имеют право на медицинское обеспечение и санаторно-курортное лечение, предусмотренные федеральными законами и иными нормативными правовыми актами Российской Федерации для военнослужащих (сотрудников), граждан Российской Федерации, уволенных с военной службы из внутренних войск, уволенных с военной службы (службы) в войсках национальной гвардии, членов их семей и лиц, находящихся на иждивении сотрудников (граждан Российской Федерации, уволенных со службы в войсках национальной гвардии). (В редакции Федерального закона от 29.07.2018 № 264-ФЗ)\n2. Медицинское обеспечение, медицинское освидетельствование, военно-врачебная экспертиза и санаторно-курортное лечение военнослужащих (сотрудников) войск национальной гвардии, граждан Российской Федерации, уволенных с военной службы из внутренних войск, уволенных с военной службы (службы) в войсках национальной гвардии, членов их семей и лиц, находящихся на иждивении сотрудников (граждан Российской Федерации, уволенных со службы в войсках национальной гвардии), на которых в соответствии с федеральными законами и иными нормативными правовыми актами Российской Федерации распространяются права и социальные гарантии по медицинскому обеспечению и санаторно-курортному лечению, установленные для военнослужащих (сотрудников), членов их семей и лиц, находящихся на иждивении сотрудников (граждан Российской Федерации, уволенных со службы в войсках национальной гвардии), осуществляются в медицинских организациях уполномоченного федерального органа исполнительной власти либо федерального органа исполнительной власти в сфере внутренних дел в порядке, определяемом Правительством Российской Федерации, за счет средств, предусмотренных в федеральном бюджете соответственно уполномоченному федеральному органу исполнительной власти, федеральному органу исполнительной власти в сфере внутренних дел на эти цели. (В редакции Федерального закона от 29.07.2018 № 264-ФЗ)\n3. Медицинская помощь военнослужащим (сотрудникам) войск национальной гвардии организуется в соответствии с порядками оказания медицинской помощи и на основе стандартов медицинской помощи, утвержденных федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере здравоохранения.\n4. Сотруднику, выполнявшему задачи по обеспечению правопорядка и общественной безопасности в отдельных регионах Российской Федерации, а также сотруднику, проходившему службу в условиях военного положения или чрезвычайного положения, вооруженного конфликта, проведения контртеррористической операции, ликвидации последствий аварий, катастроф природного и техногенного характера, других чрезвычайных ситуаций и в иных особых условиях, связанных с повышенной опасностью для жизни и здоровья, при наличии показаний к медико-психологической реабилитации в трехмесячный срок предоставляется дополнительный отпуск продолжительностью до 30 суток. Предусмотренная настоящей частью медико-психологическая реабилитация сотрудника проводится бесплатно. Перечень показаний к медико-психологической реабилитации и соответствующая им продолжительность медико-психологической реабилитации, перечень категорий сотрудников, подлежащих при наличии указанных показаний медико-психологической реабилитации, порядок и места проведения медико-психологической реабилитации определяются руководителем уполномоченного федерального органа исполнительной власти.\n5. Особенности организации оказания медицинской помощи в медицинских организациях уполномоченного федерального органа исполнительной власти, в том числе при санаторно-курортном лечении, военнослужащим, сотрудникам, гражданам Российской Федерации, уволенным с военной службы из внутренних войск, уволенным с военной службы (службы) в войсках национальной гвардии, членам их семей и лицам, находящимся на иждивении сотрудников (граждан Российской Федерации, уволенных со службы в войсках национальной гвардии), устанавливаются руководителем уполномоченного федерального органа исполнительной власти, если иное не предусмотрено законодательством Российской Федерации. (В редакции Федерального закона от 29.07.2018 № 264-ФЗ)\n6. Медицинские подразделения (медицинские роты, медицинские пункты, лазареты, центры) соединений, воинских частей и организаций войск национальной гвардии осуществляют свою деятельность без лицензирования."],
["28.1","Гарантии членам семьи и близким родственникам сотрудника в связи с прохождением службы в войсках национальной гвардии","Глава 5. Гарантии правовой и социальной защиты военнослужащих (сотрудников) войск национальной гвардии","2026-08-04","Статья 28.1. Гарантии членам семьи и близким родственникам сотрудника в связи с прохождением службы в войсках национальной гвардии\n1. Детям сотрудника, погибшего (умершего) вследствие увечья или иного повреждения здоровья (заболевания), полученных при выполнении задач в ходе проведения специальной военной операции, по отражению вооруженного вторжения на территорию Российской Федерации, а также в ходе вооруженной провокации на Государственной границе Российской Федерации и территориях субъектов Российской Федерации, прилегающих к районам проведения специальной военной операции, в том числе усыновленным (удочеренным) или находящимся под опекой или попечительством в семье, включая приемную семью либо в случаях, предусмотренных законами субъектов Российской Федерации, патронатную семью, предоставляются во внеочередном порядке места в государственных и муниципальных общеобразовательных и дошкольных образовательных организациях по месту жительства их семей, а также места в летних оздоровительных лагерях. (В редакции Федерального закона от 04.08.2026 № 328-ФЗ)\n2. В случае тяжелой болезни сотрудника, в том числе вследствие полученного увечья (ранения, травмы, контузии), двум членам его семьи или двум близким родственникам оплачивается стоимость проезда железнодорожным, воздушным, водным и автомобильным (за исключением такси) транспортом от места их жительства до места нахождения больного и обратно один раз за время болезни в порядке, определяемом руководителем уполномоченного федерального органа исполнительной власти.\n3. Для целей настоящей статьи под близкими родственниками сотрудника понимаются отец (мать), отец (мать) супруга, сын (дочь), полнородные (неполнородные) братья и сестры.\n(Дополнение статьей - Федеральный закон от 24.06.2023 № 281-ФЗ) (В редакции Федерального закона от 25.04.2026 № 109-ФЗ)"],
["29","Право военнослужащих (сотрудников) войск национальной гвардии на бесплатный проезд","Глава 5. Гарантии правовой и социальной защиты военнослужащих (сотрудников) войск национальной гвардии","","Статья 29. Право военнослужащих (сотрудников) войск национальной гвардии на бесплатный проезд\n1. Военнослужащие (сотрудники) войск национальной гвардии, участвующие в охране общественного порядка, обеспечении общественной безопасности в служебных целях, обеспечиваются проездными документами на все виды транспорта общего пользования (кроме такси) городского, пригородного и местного сообщения в порядке, устанавливаемом Правительством Российской Федерации.\n2. Военнослужащие (сотрудники) войск национальной гвардии при осуществлении полномочий по доставлению задержанных лиц пользуются правом проезда и провоза задержанных лиц на всех видах транспорта общего пользования (кроме такси) городского, пригородного и местного сообщения без приобретения проездных документов, а в сельской местности на попутном транспорте по предъявлении служебного удостоверения.\n3. Военнослужащие (сотрудники) войск национальной гвардии, несущие службу на железнодорожных и водных коммуникациях либо в районах, на территориях которых введен режим чрезвычайного или военного положения, в служебных целях при непосредственном обеспечении мероприятий по охране коммуникаций и обеспечении режима чрезвычайного или военного положения имеют право на бесплатный проезд в поездах, на морских или речных судах в пределах территорий охраняемых коммуникаций и территорий указанных районов без приобретения проездных документов по предъявлении служебного удостоверения."],
["30","Финансовое обеспечение войск национальной гвардии","Глава 6. Финансовое и материально-техническое обеспечение войск национальной гвардии","2023-08-04","Статья 30. Финансовое обеспечение войск национальной гвардии\n1. Финансовое обеспечение войск национальной гвардии является расходным обязательством Российской Федерации.\n1.1. Органы государственной власти субъектов Российской Федерации и органы местного самоуправления в соответствии с законодательством Российской Федерации вправе осуществлять по предметам совместного ведения Российской Федерации и субъектов Российской Федерации расходы на реализацию возложенных на войска национальной гвардии обязанностей по охране общественного порядка и обеспечению общественной безопасности. Расходы бюджетов субъектов Российской Федерации и местных бюджетов на указанные цели осуществляются в соответствии с бюджетным законодательством Российской Федерации. (Дополнение частью - Федеральный закон от 04.08.2023 № 436-ФЗ)\n2. Средства, получаемые войсками национальной гвардии по договорам возмездного оказания услуг по охране имущества и объектов граждан и организаций и иных услуг, связанных с обеспечением охраны имущества по этим договорам, являются доходами федерального бюджета и после возмещения убытков в связи с кражами и обстоятельствами, предусмотренными условиями договоров, зачисляются в федеральный бюджет в соответствии с бюджетным законодательством Российской Федерации в полном объеме.\n2.1. Средства, получаемые войсками национальной гвардии по договорам возмездного оказания услуг, связанных с обеспечением безопасности высших должностных лиц субъектов Российской Федерации (руководителей высших исполнительных органов государственной власти субъектов Российской Федерации) и иных лиц, являются доходами федерального бюджета и зачисляются в федеральный бюджет в соответствии с бюджетным законодательством Российской Федерации в полном объеме. (Дополнение частью - Федеральный закон от 07.03.2018 № 40-ФЗ)\n3. Тарифы на оказываемые войсками национальной гвардии услуги по охране имущества и объектов граждан и организаций, а также на иные услуги, связанные с обеспечением охраны имущества, определяются в порядке, устанавливаемом Правительством Российской Федерации.\n4. Тарифы на оказываемые войсками национальной гвардии услуги, связанные с обеспечением безопасности высших должностных лиц субъектов Российской Федерации (руководителей высших исполнительных органов государственной власти субъектов Российской Федерации) и иных лиц, определяются в порядке, устанавливаемом Правительством Российской Федерации. (Дополнение частью - Федеральный закон от 07.03.2018 № 40-ФЗ)"],
["31","Материально-техническое обеспечение войск национальной гвардии","Глава 6. Финансовое и материально-техническое обеспечение войск национальной гвардии","2026-08-04","Статья 31. Материально-техническое обеспечение войск национальной гвардии\n1. Обеспечение войск национальной гвардии вооружением, боеприпасами, военной и специальной техникой, специальными средствами осуществляется в порядке, устанавливаемом Правительством Российской Федерации, и по нормам, устанавливаемым уполномоченным федеральным органом исполнительной власти. Порядок и нормы иных видов материально-технического обеспечения войск национальной гвардии устанавливаются уполномоченным федеральным органом исполнительной власти, если иное не установлено федеральными законами. (В редакции Федерального закона от 04.08.2023 № 446-ФЗ)\n1.1. Порядок обеспечения, владения, пользования и распоряжения вещевым имуществом сотрудников войск национальной гвардии устанавливается уполномоченным федеральным органом исполнительной власти. (Дополнение частью - Федеральный закон от 04.08.2026 № 330-ФЗ)\n2. Закупка товаров, работ и услуг в сфере деятельности войск национальной гвардии осуществляется в соответствии с законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок товаров, работ и услуг для обеспечения государственных и муниципальных нужд.\n3. Строительство, реконструкция или предоставление объектов, предназначенных для размещения органов управления войсками национальной гвардии, соединений, воинских частей, подразделений и организаций войск национальной гвардии, и расходование горючего и смазочных материалов производятся в порядке и по нормам, которые установлены для Вооруженных Сил Российской Федерации (с учетом особенностей, определяемых руководителем уполномоченного федерального органа исполнительной власти).\n4. Расквартирование воинских частей, выполняющих задачи по охране важных государственных объектов, специальных грузов, сооружений на коммуникациях, а также строительство, капитальный ремонт, реконструкция, материально-техническое обеспечение военных городков, зданий и сооружений, предназначенных для расквартирования указанных воинских частей, инженерно-технических средств охраны, караульных помещений, зданий (помещений) комендатур, бюро пропусков, обеспечение содержания и эксплуатации указанного в настоящей части имущества (в том числе предоставление и оплата коммунальных услуг), обеспечение личного состава караулов на объектах, производящих или применяющих в производстве радиоактивные, аварийно-опасные и химически опасные вещества, средствами индивидуальной и коллективной защиты, приборами радиационного и химического наблюдения, дозиметрического контроля и системами аварийного оповещения осуществляются за счет средств организаций, важные государственные объекты, и (или) специальные грузы, и (или) сооружения на коммуникациях которых подлежат охране войсками национальной гвардии в соответствии с перечнями, утвержденными Правительством Российской Федерации. (В редакции Федерального закона от 26.05.2021 № 147-ФЗ)\n5. Обеспечение подразделений войск национальной гвардии, осуществляющих на договорной основе охрану имущества граждан и организаций, а также охрану объектов, техническими средствами охраны, выделение указанным подразделениям служебных и подсобных помещений с оборудованием и инвентарем, проведение капитального ремонта, реконструкции и обеспечение технической эксплуатации (водоснабжение, отопление, освещение, уборка, ремонт) указанных помещений являются обязательствами организаций, заключивших договоры об охране имущества и объектов.\n6. Для организации охраны объектов, подключенных к пультам централизованного наблюдения, войска национальной гвардии используют каналы связи, предоставляемые операторами связи в соответствии с законодательством Российской Федерации в области связи. Помещения (части помещений) в сооружениях связи, используемые для размещения аппаратуры охранной сигнализации, арендуются у операторов связи на договорной основе.\n7. Личный состав войск национальной гвардии, привлекаемый к выполнению служебно-боевых (оперативно-служебных, служебных, боевых) задач за пределами пунктов их постоянной дислокации, обеспечивается дополнительным питанием.\n8. Субъекты транспортной инфраструктуры предоставляют на безвозмездной основе войскам национальной гвардии для участия в охране общественного порядка и обеспечении общественной безопасности на железнодорожном, водном, воздушном транспорте и метрополитенах служебные и подсобные помещения, оборудование, средства и услуги связи. Оборудование помещений мебелью, оргтехникой и средствами связи и обеспечение технической эксплуатации этих помещений (водоснабжение, отопление, освещение, уборка, ремонт) осуществляются за счет средств, предусмотренных в федеральном бюджете уполномоченному федеральному органу исполнительной власти. (Дополнение частью - Федеральный закон от 29.07.2018 № 264-ФЗ)"],
["32","Имущество войск национальной гвардии, порядок использования земельных участков","Глава 6. Финансовое и материально-техническое обеспечение войск национальной гвардии","","Статья 32. Имущество войск национальной гвардии, порядок использования земельных участков\n1. Используемые войсками национальной гвардии земельные участки, а также здания, сооружения, техника и другое имущество войск национальной гвардии, созданное (создаваемое) или приобретенное (приобретаемое) за счет бюджетных ассигнований федерального бюджета и иных источников финансирования, являются федеральной собственностью. Земельные участки находятся в постоянном (бессрочном) пользовании, а имущество - в оперативном управлении уполномоченного федерального органа исполнительной власти.\n2. Земельные участки, военные городки, здания и сооружения, занимаемые органами управления, соединениями и воинскими частями войск национальной гвардии, находящиеся в собственности, безвозмездном пользовании, постоянном (бессрочном) пользовании, хозяйственном ведении или оперативном управлении организаций, важные государственные объекты, и (или) специальные грузы, и (или) сооружения на коммуникациях которых подлежат охране войсками национальной гвардии в соответствии с перечнями, утверждаемыми Правительством Российской Федерации, в случае исключения данных объектов, специальных грузов, сооружений на коммуникациях из указанных перечней закрепляются за войсками национальной гвардии в порядке, определенном Правительством Российской Федерации."],
["33","Прокурорский надзор","Глава 7. Прокурорский надзор за деятельностью войск национальной гвардии","","Статья 33. Прокурорский надзор\nНадзор за исполнением войсками национальной гвардии федеральных конституционных законов и федеральных законов осуществляют Генеральный прокурор Российской Федерации и подчиненные ему прокуроры."],
["34","Заключительные положения","Глава 8. Заключительные положения","2023-02-06","Статья 34. Заключительные положения\n1. Военнослужащие внутренних войск Министерства внутренних дел Российской Федерации и сотрудники органов внутренних дел, проходившие военную службу (службу) по контракту до 5 апреля 2016 года, а также граждане Российской Федерации, принятые на военную службу (службу) после указанной даты до утверждения штатов соответствующих органов управления, объединений, соединений, воинских частей, подразделений (органов), военных образовательных организаций высшего образования и иных организаций войск национальной гвардии, продолжают проходить военную службу (службу) в войсках национальной гвардии в соответствии с условиями ранее заключенных контрактов о прохождении военной службы (службы) без переаттестации и переназначения. Таким военнослужащим (сотрудникам) сохраняются воинские (специальные) звания, а также ранее присвоенная классная квалификация (квалификационная категория, квалификационный класс, квалификационные звания) на срок, на который она была присвоена. (В редакции Федерального закона от 29.07.2018 № 264-ФЗ)\n2. Военные образовательные организации высшего образования, учебные воинские части (центры, учебные подразделения), иные организации, имеющие лицензии на осуществление образовательной деятельности и свидетельства о государственной аккредитации, выданные им до 5 апреля 2016 года, осуществляют образовательную деятельность на основании указанных лицензий и свидетельств до окончания срока их действия.\n3. Лицензии на осуществление медицинской деятельности, фармацевтической деятельности, а также деятельности, связанной с оборотом наркотических средств, психотропных веществ и их прекурсоров, в том числе с правом на их перевозку, выданные медицинским организациям войск национальной гвардии до 5 апреля 2016 года, не подлежат переоформлению и действуют до истечения указанного в них срока.\n4. Договор обязательного государственного страхования, заключенный федеральным органом исполнительной власти в сфере внутренних дел в соответствии с Федеральным законом от 28 марта 1998 года № 52-ФЗ \"Об обязательном государственном страховании жизни и здоровья военнослужащих, граждан, призванных на военные сборы, лиц рядового и начальствующего состава органов внутренних дел Российской Федерации, Государственной противопожарной службы, органов по контролю за оборотом наркотических средств и психотропных веществ, сотрудников учреждений и органов уголовно-исполнительной системы, сотрудников войск национальной гвардии Российской Федерации, сотрудников органов принудительного исполнения Российской Федерации\" на день вступления в силу настоящего Федерального закона, действует в отношении военнослужащих и сотрудников, проходящих военную службу (службу) в войсках национальной гвардии, до окончания срока его действия. (В редакции Федерального закона от 01.10.2019 № 328-ФЗ)\n5. Материально-техническое обеспечение войск национальной гвардии до завершения формирования органов материально-технического обеспечения войск национальной гвардии осуществляется через органы обеспечения (снабжения) федерального органа исполнительной власти в сфере внутренних дел в порядке, определяемом Правительством Российской Федерации.\n6. До оборудования в территориальных органах уполномоченного федерального органа исполнительной власти помещений для хранения оружия полицией осуществляются функции по хранению изъятых, добровольно сданных и найденных огнестрельного, газового, холодного и иного оружия, боеприпасов, патронов к оружию, взрывных устройств, взрывчатых веществ, основных частей огнестрельного оружия. (В редакции Федерального закона от 06.02.2023 № 14-ФЗ)\n7. Изымаемые войсками национальной гвардии в соответствии с пунктом 24 части 1 статьи 9 настоящего Федерального закона оружие, боеприпасы, патроны к оружию, основные части огнестрельного оружия передаются в территориальные органы федерального органа исполнительной власти в сфере внутренних дел для временного хранения на срок, не превышающий четырех месяцев, до возврата их собственнику на основании решения территориального органа уполномоченного федерального органа исполнительной власти или передачи в территориальный орган уполномоченного федерального органа исполнительной власти. (В редакции Федерального закона от 06.02.2023 № 14-ФЗ)\n8. Порядок передачи изъятых, добровольно сданных и найденных огнестрельного, газового, холодного и иного оружия, боеприпасов, патронов к оружию, взрывных устройств, взрывчатых веществ, основных частей огнестрельного оружия между органами внутренних дел (полицией) и территориальными органами уполномоченного федерального органа исполнительной власти определяется уполномоченным федеральным органом исполнительной власти и федеральным органом исполнительной власти в сфере внутренних дел. (Дополнение частью - Федеральный закон от 06.02.2023 № 14-ФЗ)"],
["35","Порядок вступления в силу настоящего Федерального закона","Глава 8. Заключительные положения","","Статья 35. Порядок вступления в силу настоящего Федерального закона\n1. Настоящий Федеральный закон вступает в силу со дня его официального опубликования, за исключением пунктов 12, 17 и 19 части 1 статьи 9 настоящего Федерального закона.\n2. Пункты 12, 17 и 19 части 1 статьи 9 настоящего Федерального закона вступают в силу с 1 января 2018 года.\nПрезидент Российской Федерации В.Путин\nМосква, Кремль 3 июля 2016 года № 226-ФЗ"]
];
